window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["NAM"]={"book":"NAM","editions":{"hbo-source":[[1,1,"מַשָּׂ֖א נִֽינְוֵ֑ה סֵ֧פֶר חֲז֛וֹן נַח֖וּם הָ⁠אֶלְקֹשִֽׁי׃","maşá֖̇̂ʼ niֽynĕwé֑h sé֧per ẖàz֛wòn naẖ֖ẇm há⁠ʼelĕqòşǐֽy׃"],[1,2,"אֵ֣ל קַנּ֤וֹא וְ⁠נֹקֵם֙ יְהוָ֔ה נֹקֵ֥ם יְהוָ֖ה וּ⁠בַ֣עַל חֵמָ֑ה נֹקֵ֤ם יְהוָה֙ לְ⁠צָרָ֔י⁠ו וְ⁠נוֹטֵ֥ר ה֖וּא לְ⁠אֹיְבָֽי⁠ו׃","ʼé֣l qaṅ֤wòʼ wĕ⁠nòqém֙ yĕhwá֔h nòqé֥m yĕhwá֖h ẇ⁠ba֣ʻal ẖémá֑h nòqé֤m yĕhwáh֙ lĕ⁠ẕárá֔y⁠w wĕ⁠nwòté֥r h֖ẇʼ lĕ⁠ʼòyĕbáֽy⁠w׃"],[1,3,"יְהֹוָ֗ה אֶ֤רֶךְ אַפַּ֨יִם֙ ו⁠גדול־כֹּ֔חַ וְ⁠נַקֵּ֖ה לֹ֣א יְנַקֶּ֑ה יְהוָ֗ה בְּ⁠סוּפָ֤ה וּ⁠בִ⁠שְׂעָרָה֙ דַּרְכּ֔⁠וֹ וְ⁠עָנָ֖ן אֲבַ֥ק רַגְלָֽי⁠ו׃","yĕhòwá֗h ʼe֤rekĕ ʼapȧ֨yim֙ w⁠gdwl-kò̇֔ẖa wĕ⁠naqé֖̇h lò֣ʼ yĕnaqė֑h yĕhwá֗h bĕ̇⁠sẇpá֤h ẇ⁠bi⁠şĕ̂ʻáráh֙ dȧrĕk̇֔⁠wò wĕ⁠ʻáná֖n ʼàba֥q ragĕláֽy⁠w׃"],[1,4,"גּוֹעֵ֤ר בַּ⁠יָּם֙ וַֽ⁠יַּבְּשֵׁ֔⁠הוּ וְ⁠כָל־הַ⁠נְּהָר֖וֹת הֶֽחֱרִ֑יב אֻמְלַ֤ל בָּשָׁן֙ וְ⁠כַרְמֶ֔ל וּ⁠פֶ֥רַח לְבָנ֖וֹן אֻמְלָֽל׃","ġwòʻé֤r bȧ⁠yá̇m֙ waֽ⁠yȧbĕ̇şé̌֔⁠hẇ wĕ⁠kál-ha⁠nĕ̇hár֖wòţ heֽẖèri֑yb ʼumĕla֤l bá̇şá̌n֙ wĕ⁠karĕme֔l ẇ⁠pe֥raẖ lĕbán֖wòn ʼumĕláֽl׃"],[1,5,"הָרִים֙ רָעֲשׁ֣וּ מִמֶּ֔⁠נּוּ וְ⁠הַ⁠גְּבָע֖וֹת הִתְמֹגָ֑גוּ וַ⁠תִּשָּׂ֤א הָ⁠אָ֨רֶץ֙ מִ⁠פָּנָ֔י⁠ו וְ⁠תֵבֵ֖ל וְ⁠כָל־יֹ֥שְׁבֵי בָֽ⁠הּ׃","háriym֙ ráʻàş֣̌ẇ mimė֔⁠ṅẇ wĕ⁠ha⁠gĕ̇báʻ֖wòţ hiţĕmògá֑gẇ wa⁠ţi̇şá֤̇̂ʼ há⁠ʼá֨reẕ֙ mi⁠pá̇ná֔y⁠w wĕ⁠ţébé֖l wĕ⁠kál-yò֥şĕ̌béy báֽ⁠ḣ׃"],[1,6,"לִ⁠פְנֵ֤י זַעְמ⁠וֹ֙ מִ֣י יַֽעֲמ֔וֹד וּ⁠מִ֥י יָק֖וּם בַּ⁠חֲר֣וֹן אַפּ֑⁠וֹ חֲמָת⁠וֹ֙ נִתְּכָ֣ה כָ⁠אֵ֔שׁ וְ⁠הַ⁠צֻּרִ֖ים נִתְּצ֥וּ מִמֶּֽ⁠נּוּ׃","li⁠pĕné֤y zaʻĕm⁠wò֙ mi֣y yaֽʻàm֔wòd ẇ⁠mi֥y yáq֖ẇm bȧ⁠ẖàr֣wòn ʼaṗ֑⁠wò ẖàmáţ⁠wò֙ niţĕ̇ká֣h ká⁠ʼé֔ş̌ wĕ⁠ha⁠ẕu̇ri֖ym niţĕ̇ẕ֥ẇ mimėֽ⁠ṅẇ׃"],[1,7,"ט֣וֹב יְהוָ֔ה לְ⁠מָע֖וֹז בְּ⁠י֣וֹם צָרָ֑ה וְ⁠יֹדֵ֖עַ חֹ֥סֵי בֽ⁠וֹ׃","t֣wòb yĕhwá֔h lĕ⁠máʻ֖wòz bĕ̇⁠y֣wòm ẕárá֑h wĕ⁠yòdé֖ʻa ẖò֥séy bֽ⁠wò׃"],[1,8,"וּ⁠בְ⁠שֶׁ֣טֶף עֹבֵ֔ר כָּלָ֖ה יַעֲשֶׂ֣ה מְקוֹמָ֑⁠הּ וְ⁠אֹיְבָ֖י⁠ו יְרַדֶּף־חֹֽשֶׁךְ׃","ẇ⁠bĕ⁠şě֣tep ʻòbé֔r ká̇lá֖h yaʻàşê֣h mĕqwòmá֑⁠ḣ wĕ⁠ʼòyĕbá֖y⁠w yĕradėp-ẖòֽşěkĕ׃"],[1,9,"מַה־תְּחַשְּׁבוּ⁠ן֙ אֶל־יְהוָ֔ה כָּלָ֖ה ה֣וּא עֹשֶׂ֑ה לֹֽא־תָק֥וּם פַּעֲמַ֖יִם צָרָֽה׃","mah-ţĕ̇ẖaşĕ̇̌bẇ⁠n֙ ʼel-yĕhwá֔h ká̇lá֖h h֣ẇʼ ʻòşê֑h lòֽʼ-ţáq֥ẇm pȧʻàma֖yim ẕáráֽh׃"],[1,10,"כִּ֚י עַד־סִירִ֣ים סְבֻכִ֔ים וּ⁠כְ⁠סָבְאָ֖⁠ם סְבוּאִ֑ים אֻ֨כְּל֔וּ כְּ⁠קַ֥שׁ יָבֵ֖שׁ מָלֵֽא׃","ki֚̇y ʻad-siyri֣ym sĕbuki֔ym ẇ⁠kĕ⁠sábĕʼá֖⁠m sĕbẇʼi֑ym ʼu֨kĕ̇l֔ẇ kĕ̇⁠qa֥ş̌ yábé֖ş̌ máléֽʼ׃"],[1,11,"מִמֵּ֣⁠ךְ יָצָ֔א חֹשֵׁ֥ב עַל־יְהוָ֖ה רָעָ֑ה יֹעֵ֖ץ בְּלִיָּֽעַל׃ס","mimé֣̇⁠kĕ yáẕá֔ʼ ẖòşé֥̌b ʻal-yĕhwá֖h ráʻá֑h yòʻé֖ẕ bĕ̇liyáֽ̇ʻal׃s"],[1,12,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אִם־שְׁלֵמִים֙ וְ⁠כֵ֣ן רַבִּ֔ים וְ⁠כֵ֥ן נָגֹ֖זּוּ וְ⁠עָבָ֑ר וְ⁠עִ֨נִּתִ֔⁠ךְ לֹ֥א אֲעַנֵּ֖⁠ךְ עֽוֹד׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼim-şĕ̌lémiym֙ wĕ⁠ké֣n rabi̇֔ym wĕ⁠ké֥n nágò֖żẇ wĕ⁠ʻábá֑r wĕ⁠ʻi֨ni̇ţi֔⁠kĕ lò֥ʼ ʼàʻané֖̇⁠kĕ ʻֽwòd׃"],[1,13,"וְ⁠עַתָּ֕ה אֶשְׁבֹּ֥ר מֹטֵ֖⁠הוּ מֵֽ⁠עָלָ֑יִ⁠ךְ וּ⁠מוֹסְרֹתַ֖יִ⁠ךְ אֲנַתֵּֽק׃","wĕ⁠ʻaţá̇֕h ʼeşĕ̌bò֥̇r mòté֖⁠hẇ méֽ⁠ʻálá֑yi⁠kĕ ẇ⁠mwòsĕròţa֖yi⁠kĕ ʼànaţéֽ̇q׃"],[1,14,"וְ⁠צִוָּ֤ה עָלֶ֨י⁠ךָ֙ יְהוָ֔ה לֹֽא־יִזָּרַ֥ע מִ⁠שִּׁמְ⁠ךָ֖ ע֑וֹד מִ⁠בֵּ֨ית אֱלֹהֶ֜י⁠ךָ אַכְרִ֨ית פֶּ֧סֶל וּ⁠מַסֵּכָ֛ה אָשִׂ֥ים קִבְרֶ֖⁠ךָ כִּ֥י קַלּֽוֹתָ׃פ","wĕ⁠ẕiwá֤̇h ʻále֨y⁠ká֙ yĕhwá֔h lòֽʼ-yizá̇ra֥ʻ mi⁠şi̇̌mĕ⁠ká֖ ʻ֑wòd mi⁠bé̇֨yţ ʼèlòhe֜y⁠ká ʼakĕri֨yţ pė֧sel ẇ⁠masé̇ká֛h ʼáşî֥ym qibĕre֖⁠ká ki֥̇y qalֽ̇wòţá׃p"],[1,15,"הִנֵּ֨ה עַל־הֶ⁠הָרִ֜ים רַגְלֵ֤י מְבַשֵּׂר֙ מַשְׁמִ֣יעַ שָׁל֔וֹם חָגִּ֧י יְהוּדָ֛ה חַגַּ֖יִ⁠ךְ שַׁלְּמִ֣י נְדָרָ֑יִ⁠ךְ כִּי֩ לֹ֨א יוֹסִ֥יף ע֛וֹד ל⁠עבור־בָּ֥⁠ךְ בְּלִיַּ֖עַל כֻּלֹּ֥⁠ה נִכְרָֽת׃","hiné̇֨h ʻal-he⁠hári֜ym ragĕlé֤y mĕbaşé̇̂r֙ maşĕ̌mi֣yʻa şá̌l֔wòm ẖági֧̇y yĕhẇdá֛h ẖagȧ֖yi⁠kĕ şǎlĕ̇mi֣y nĕdárá֑yi⁠kĕ ki̇y֩ lò֨ʼ ywòsi֥yp ʻ֛wòd l⁠ʻbwr-bá֥̇⁠kĕ bĕ̇liyȧ֖ʻal ku̇lò֥̇⁠h nikĕráֽţ׃"],[2,1,"עָלָ֥ה מֵפִ֛יץ עַל־פָּנַ֖יִ⁠ךְ נָצ֣וֹר מְצֻרָ֑ה צַפֵּה־דֶ֨רֶךְ֙ חַזֵּ֣ק מָתְנַ֔יִם אַמֵּ֥ץ כֹּ֖חַ מְאֹֽד׃","ʻálá֥h mépi֛yẕ ʻal-pá̇na֖yi⁠kĕ náẕ֣wòr mĕẕurá֑h ẕapé̇h-de֨rekĕ֙ ẖazé֣̇q máţĕna֔yim ʼamé֥̇ẕ kò֖̇ẖa mĕʼòֽd׃"],[2,2,"כִּ֣י שָׁ֤ב יְהוָה֙ אֶת־גְּא֣וֹן יַעֲקֹ֔ב כִּ⁠גְא֖וֹן יִשְׂרָאֵ֑ל כִּ֤י בְקָקוּ⁠ם֙ בֹּֽקְקִ֔ים וּ⁠זְמֹרֵי⁠הֶ֖ם שִׁחֵֽתוּ׃","ki֣̇y şá֤̌b yĕhwáh֙ ʼeţ-gĕ̇ʼ֣wòn yaʻàqò֔b ki̇⁠gĕʼ֖wòn yişĕ̂ráʼé֑l ki֤̇y bĕqáqẇ⁠m֙ bòֽ̇qĕqi֔ym ẇ⁠zĕmòréy⁠he֖m şǐẖéֽţẇ׃"],[2,3,"מָגֵ֨ן גִּבֹּרֵ֜י⁠הוּ מְאָדָּ֗ם אַנְשֵׁי־חַ֨יִל֙ מְתֻלָּעִ֔ים בְּ⁠אֵשׁ־פְּלָד֥וֹת הָ⁠רֶ֖כֶב בְּ⁠י֣וֹם הֲכִינ֑⁠וֹ וְ⁠הַ⁠בְּרֹשִׁ֖ים הָרְעָֽלוּ׃","mágé֨n gi̇bò̇ré֜y⁠hẇ mĕʼádá̇֗m ʼanĕşé̌y-ẖa֨yil֙ mĕţulá̇ʻi֔ym bĕ̇⁠ʼéş̌-pĕ̇lád֥wòţ há⁠re֖keb bĕ̇⁠y֣wòm hàkiyn֑⁠wò wĕ⁠ha⁠bĕ̇ròşǐ֖ym hárĕʻáֽlẇ׃"],[2,4,"בַּֽ⁠חוּצוֹת֙ יִתְהוֹלְל֣וּ הָ⁠רֶ֔כֶב יִֽשְׁתַּקְשְׁק֖וּ⁠ן בָּ⁠רְחֹב֑וֹת מַרְאֵי⁠הֶן֙ כַּ⁠לַּפִּידִ֔ם כַּ⁠בְּרָקִ֖ים יְרוֹצֵֽצוּ׃","bȧֽ⁠ẖẇẕwòţ֙ yiţĕhwòlĕl֣ẇ há⁠re֔keb yiֽşĕ̌ţȧqĕşĕ̌q֖ẇ⁠n bá̇⁠rĕẖòb֑wòţ marĕʼéy⁠hen֙ kȧ⁠lȧpi̇ydi֔m kȧ⁠bĕ̇ráqi֖ym yĕrwòẕéֽẕẇ׃"],[2,5,"יִזְכֹּר֙ אַדִּירָ֔י⁠ו יִכָּשְׁל֖וּ ב⁠הלכות⁠ם יְמַֽהֲרוּ֙ חֽוֹמָתָ֔⁠הּ וְ⁠הֻכַ֖ן הַ⁠סֹּכֵֽךְ׃","yizĕkò̇r֙ ʼadi̇yrá֔y⁠w yiká̇şĕ̌l֖ẇ b⁠hlkwţ⁠m yĕmaֽhàrẇ֙ ẖֽwòmáţá֔⁠ḣ wĕ⁠huka֖n ha⁠sò̇kéֽkĕ׃"],[2,6,"שַׁעֲרֵ֥י הַ⁠נְּהָר֖וֹת נִפְתָּ֑חוּ וְ⁠הַֽ⁠הֵיכָ֖ל נָמֽוֹג׃","şǎʻàré֥y ha⁠nĕ̇hár֖wòţ nipĕţá֑̇ẖẇ wĕ⁠haֽ⁠héyká֖l námֽwòg׃"],[2,7,"וְ⁠הֻצַּ֖ב גֻּלְּתָ֣ה הֹֽעֲלָ֑תָה וְ⁠אַמְהֹתֶ֗י⁠הָ מְנַֽהֲגוֹת֙ כְּ⁠ק֣וֹל יוֹנִ֔ים מְתֹפְפֹ֖ת עַל־לִבְבֵ⁠הֶֽן׃","wĕ⁠huẕȧ֖b gu̇lĕ̇ţá֣h hòֽʻàlá֑ţáh wĕ⁠ʼamĕhòţe֗y⁠há mĕnaֽhàgwòţ֙ kĕ̇⁠q֣wòl ywòni֔ym mĕţòpĕpò֖ţ ʻal-libĕbé⁠heֽn׃"],[2,8,"וְ⁠נִינְוֵ֥ה כִ⁠בְרֵֽכַת־מַ֖יִם מִ֣⁠ימֵי הִ֑יא וְ⁠הֵ֣מָּה נָסִ֔ים עִמְד֥וּ עֲמֹ֖דוּ וְ⁠אֵ֥ין מַפְנֶֽה׃","wĕ⁠niynĕwé֥h ki⁠bĕréֽkaţ-ma֖yim mi֣⁠yméy hi֑yʼ wĕ⁠hé֣má̇h nási֔ym ʻimĕd֥ẇ ʻàmò֖dẇ wĕ⁠ʼé֥yn mapĕneֽh׃"],[2,9,"בֹּ֥זּוּ כֶ֖סֶף בֹּ֣זּוּ זָהָ֑ב וְ⁠אֵ֥ין קֵ֨צֶה֙ לַ⁠תְּכוּנָ֔ה כָּבֹ֕ד מִ⁠כֹּ֖ל כְּלִ֥י חֶמְדָּֽה׃","bò֥̇żẇ ke֖sep bò֣̇żẇ záhá֑b wĕ⁠ʼé֥yn qé֨ẕeh֙ la⁠ţĕ̇kẇná֔h ká̇bò֕d mi⁠kò֖̇l kĕ̇li֥y ẖemĕdáֽ̇h׃"],[2,10,"בּוּקָ֥ה וּ⁠מְבוּקָ֖ה וּ⁠מְבֻלָּקָ֑ה וְ⁠לֵ֨ב נָמֵ֜ס וּ⁠פִ֣ק בִּרְכַּ֗יִם וְ⁠חַלְחָלָה֙ בְּ⁠כָל־מָתְנַ֔יִם וּ⁠פְנֵ֥י כֻלָּ֖⁠ם קִבְּצ֥וּ פָארֽוּר׃","ḃẇqá֥h ẇ⁠mĕbẇqá֖h ẇ⁠mĕbulá̇qá֑h wĕ⁠lé֨b námé֜s ẇ⁠pi֣q bi̇rĕkȧ֗yim wĕ⁠ẖalĕẖáláh֙ bĕ̇⁠kál-máţĕna֔yim ẇ⁠pĕné֥y kulá֖̇⁠m qibĕ̇ẕ֥ẇ páʼrֽẇr׃"],[2,11,"אַיֵּה֙ מְע֣וֹן אֲרָי֔וֹת וּ⁠מִרְעֶ֥ה ה֖וּא לַ⁠כְּפִרִ֑ים אֲשֶׁ֣ר הָלַךְ֩ אַרְיֵ֨ה לָבִ֥יא שָׁ֛ם גּ֥וּר אַרְיֵ֖ה וְ⁠אֵ֥ין מַחֲרִֽיד׃","ʼayé̇h֙ mĕʻ֣wòn ʼàráy֔wòţ ẇ⁠mirĕʻe֥h h֖ẇʼ la⁠kĕ̇piri֑ym ʼàşě֣r hálakĕ֩ ʼarĕyé֨h lábi֥yʼ şá֛̌m ġ֥ẇr ʼarĕyé֖h wĕ⁠ʼé֥yn maẖàriֽyd׃"],[2,12,"אַרְיֵ֤ה טֹרֵף֙ בְּ⁠דֵ֣י גֹֽרוֹתָ֔י⁠ו וּ⁠מְחַנֵּ֖ק לְ⁠לִבְאֹתָ֑י⁠ו וַ⁠יְמַלֵּא־טֶ֣רֶף חֹרָ֔י⁠ו וּ⁠מְעֹֽנֹתָ֖י⁠ו טְרֵפָֽה׃","ʼarĕyé֤h tòrép֙ bĕ̇⁠dé֣y gòֽrwòţá֔y⁠w ẇ⁠mĕẖané֖̇q lĕ⁠libĕʼòţá֑y⁠w wa⁠yĕmalé̇ʼ-te֣rep ẖòrá֔y⁠w ẇ⁠mĕʻòֽnòţá֖y⁠w tĕrépáֽh׃"],[2,13,"הִנְ⁠נִ֣י אֵלַ֗יִ⁠ךְ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠הִבְעַרְתִּ֤י בֶֽ⁠עָשָׁן֙ רִכְבָּ֔⁠הּ וּ⁠כְפִירַ֖יִ⁠ךְ תֹּ֣אכַל חָ֑רֶב וְ⁠הִכְרַתִּ֤י מֵ⁠אֶ֨רֶץ֙ טַרְפֵּ֔⁠ךְ וְ⁠לֹֽא־יִשָּׁמַ֥ע ע֖וֹד ק֥וֹל מַלְאָכֵֽ⁠כֵה׃ס","hinĕ⁠ni֣y ʼéla֗yi⁠kĕ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠hibĕʻarĕţi֤̇y beֽ⁠ʻáşá̌n֙ rikĕbá̇֔⁠ḣ ẇ⁠kĕpiyra֖yi⁠kĕ ţò֣̇ʼkal ẖá֑reb wĕ⁠hikĕraţi֤̇y mé⁠ʼe֨reẕ֙ tarĕpé̇֔⁠kĕ wĕ⁠lòֽʼ-yişá̇̌ma֥ʻ ʻ֖wòd q֥wòl malĕʼákéֽ⁠kéh׃s"],[3,1,"ה֖וֹי עִ֣יר דָּמִ֑ים כֻּלָּ֗⁠הּ כַּ֤חַשׁ פֶּ֨רֶק֙ מְלֵאָ֔ה לֹ֥א יָמִ֖ישׁ טָֽרֶף׃","h֖wòy ʻi֣yr dá̇mi֑ym ku̇lá̇֗⁠ḣ kȧ֤ẖaş̌ pė֨req֙ mĕléʼá֔h lò֥ʼ yámi֖yş̌ táֽrep׃"],[3,2,"ק֣וֹל שׁ֔וֹט וְ⁠ק֖וֹל רַ֣עַשׁ אוֹפָ֑ן וְ⁠ס֣וּס דֹּהֵ֔ר וּ⁠מֶרְכָּבָ֖ה מְרַקֵּדָֽה׃","q֣wòl ş̌֔wòt wĕ⁠q֖wòl ra֣ʻaş̌ ʼwòpá֑n wĕ⁠s֣ẇs dò̇hé֔r ẇ⁠merĕká̇bá֖h mĕraqé̇dáֽh׃"],[3,3,"פָּרָ֣שׁ מַעֲלֶ֗ה וְ⁠לַ֤הַב חֶ֨רֶב֙ וּ⁠בְרַ֣ק חֲנִ֔ית וְ⁠רֹ֥ב חָלָ֖ל וְ⁠כֹ֣בֶד פָּ֑גֶר וְ⁠אֵ֥ין קֵ֨צֶה֙ לַ⁠גְּוִיָּ֔ה יכשלו בִּ⁠גְוִיָּתָֽ⁠ם׃","pá̇rá֣ş̌ maʻàle֗h wĕ⁠la֤hab ẖe֨reb֙ ẇ⁠bĕra֣q ẖàni֔yţ wĕ⁠rò֥b ẖálá֖l wĕ⁠kò֣bed pá֑̇ger wĕ⁠ʼé֥yn qé֨ẕeh֙ la⁠gĕ̇wiyá̇֔h ykşlw bi̇⁠gĕwiyá̇ţáֽ⁠m׃"],[3,4,"מֵ⁠רֹב֙ זְנוּנֵ֣י זוֹנָ֔ה ט֥וֹבַת חֵ֖ן בַּעֲלַ֣ת כְּשָׁפִ֑ים הַ⁠מֹּכֶ֤רֶת גּוֹיִם֙ בִּ⁠זְנוּנֶ֔י⁠הָ וּ⁠מִשְׁפָּח֖וֹת בִּ⁠כְשָׁפֶֽי⁠הָ׃","mé⁠ròb֙ zĕnẇné֣y zwòná֔h t֥wòbaţ ẖé֖n bȧʻàla֣ţ kĕ̇şá̌pi֑ym ha⁠mò̇ke֤reţ ġwòyim֙ bi̇⁠zĕnẇne֔y⁠há ẇ⁠mişĕ̌pá̇ẖ֖wòţ bi̇⁠kĕşá̌peֽy⁠há׃"],[3,5,"הִנְ⁠נִ֣י אֵלַ֗יִ⁠ךְ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠גִלֵּיתִ֥י שׁוּלַ֖יִ⁠ךְ עַל־פָּנָ֑יִ⁠ךְ וְ⁠הַרְאֵיתִ֤י גוֹיִם֙ מַעְרֵ֔⁠ךְ וּ⁠מַמְלָכ֖וֹת קְלוֹנֵֽ⁠ךְ׃","hinĕ⁠ni֣y ʼéla֗yi⁠kĕ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠gilé̇yţi֥y ş̌ẇla֖yi⁠kĕ ʻal-pá̇ná֑yi⁠kĕ wĕ⁠harĕʼéyţi֤y gwòyim֙ maʻĕré֔⁠kĕ ẇ⁠mamĕlák֖wòţ qĕlwònéֽ⁠kĕ׃"],[3,6,"וְ⁠הִשְׁלַכְתִּ֥י עָלַ֛יִ⁠ךְ שִׁקֻּצִ֖ים וְ⁠נִבַּלְתִּ֑י⁠ךְ וְ⁠שַׂמְתִּ֖י⁠ךְ כְּ⁠רֹֽאִי׃","wĕ⁠hişĕ̌lakĕţi֥̇y ʻála֛yi⁠kĕ şǐqu̇ẕi֖ym wĕ⁠nibȧlĕţi֑̇y⁠kĕ wĕ⁠şâmĕţi֖̇y⁠kĕ kĕ̇⁠ròֽʼiy׃"],[3,7,"וְ⁠הָיָ֤ה כָל־רֹאַ֨יִ⁠ךְ֙ יִדּ֣וֹד מִמֵּ֔⁠ךְ וְ⁠אָמַר֙ שָׁדְּדָ֣ה נִֽינְוֵ֔ה מִ֖י יָנ֣וּד לָ֑⁠הּ מֵ⁠אַ֛יִן אֲבַקֵּ֥שׁ מְנַחֲמִ֖ים לָֽ⁠ךְ׃","wĕ⁠háyá֤h kál-ròʼa֨yi⁠kĕ֙ yiḋ֣wòd mimé̇֔⁠kĕ wĕ⁠ʼámar֙ şá̌dĕ̇dá֣h niֽynĕwé֔h mi֖y yán֣ẇd lá֑⁠ḣ mé⁠ʼa֛yin ʼàbaqé֥̇ş̌ mĕnaẖàmi֖ym láֽ⁠kĕ׃"],[3,8,"הֲ⁠תֵֽיטְבִי֙ מִ⁠נֹּ֣א אָמ֔וֹן הַ⁠יֹּֽשְׁבָה֙ בַּ⁠יְאֹרִ֔ים מַ֖יִם סָבִ֣יב לָ֑⁠הּ אֲשֶׁר־חֵ֣יל יָ֔ם מִ⁠יָּ֖ם חוֹמָתָֽ⁠הּ׃","hà⁠ţéֽytĕbiy֙ mi⁠nò֣̇ʼ ʼám֔wòn ha⁠yòֽ̇şĕ̌báh֙ bȧ⁠yĕʼòri֔ym ma֖yim sábi֣yb lá֑⁠ḣ ʼàşěr-ẖé֣yl yá֔m mi⁠yá֖̇m ẖwòmáţáֽ⁠ḣ׃"],[3,9,"כּ֥וּשׁ עָצְמָ֛⁠ה וּ⁠מִצְרַ֖יִם וְ⁠אֵ֣ין קֵ֑צֶה פּ֣וּט וְ⁠לוּבִ֔ים הָי֖וּ בְּ⁠עֶזְרָתֵֽ⁠ךְ׃","k֥̇ẇş̌ ʻáẕĕmá֛⁠h ẇ⁠miẕĕra֖yim wĕ⁠ʼé֣yn qé֑ẕeh ṗ֣ẇt wĕ⁠lẇbi֔ym háy֖ẇ bĕ̇⁠ʻezĕráţéֽ⁠kĕ׃"],[3,10,"גַּם־הִ֗יא לַ⁠גֹּלָה֙ הָלְכָ֣ה בַ⁠שֶּׁ֔בִי גַּ֧ם עֹלָלֶ֛י⁠הָ יְרֻטְּשׁ֖וּ בְּ⁠רֹ֣אשׁ כָּל־חוּצ֑וֹת וְ⁠עַל־נִכְבַּדֶּ֨י⁠הָ֙ יַדּ֣וּ גוֹרָ֔ל וְ⁠כָל־גְּדוֹלֶ֖י⁠הָ רֻתְּק֥וּ בַ⁠זִּקִּֽים׃","gȧm-hi֗yʼ la⁠gò̇láh֙ hálĕká֣h ba⁠şė̌֔biy gȧ֧m ʻòlále֛y⁠há yĕrutĕ̇ş֖̌ẇ bĕ̇⁠rò֣ʼş̌ ká̇l-ẖẇẕ֑wòţ wĕ⁠ʻal-nikĕbȧdė֨y⁠há֙ yaḋ֣ẇ gwòrá֔l wĕ⁠kál-gĕ̇dwòle֖y⁠há ruţĕ̇q֥ẇ ba⁠zi̇qiֽ̇ym׃"],[3,11,"גַּם־אַ֣תְּ תִּשְׁכְּרִ֔י תְּהִ֖י נַֽעֲלָמָ֑ה גַּם־אַ֛תְּ תְּבַקְשִׁ֥י מָע֖וֹז מֵ⁠אוֹיֵֽב׃","gȧm-ʼa֣ţĕ̇ ţi̇şĕ̌kĕ̇ri֔y ţĕ̇hi֖y naֽʻàlámá֑h gȧm-ʼa֛ţĕ̇ ţĕ̇baqĕşǐ֥y máʻ֖wòz mé⁠ʼwòyéֽb׃"],[3,12,"כָּ֨ל־מִבְצָרַ֔יִ⁠ךְ תְּאֵנִ֖ים עִם־בִּכּוּרִ֑ים אִם־יִנּ֕וֹעוּ וְ⁠נָפְל֖וּ עַל־פִּ֥י אוֹכֵֽל׃","ká̇֨l-mibĕẕára֔yi⁠kĕ ţĕ̇ʼéni֖ym ʻim-bi̇k̇ẇri֑ym ʼim-yiṅ֕wòʻẇ wĕ⁠nápĕl֖ẇ ʻal-pi֥̇y ʼwòkéֽl׃"],[3,13,"הִנֵּ֨ה עַמֵּ֤⁠ךְ נָשִׁים֙ בְּ⁠קִרְבֵּ֔⁠ךְ לְ⁠אֹ֣יְבַ֔יִ⁠ךְ פָּת֥וֹחַ נִפְתְּח֖וּ שַׁעֲרֵ֣י אַרְצֵ֑⁠ךְ אָכְלָ֥ה אֵ֖שׁ בְּרִיחָֽיִ⁠ך׃","hiné̇֨h ʻamé֤̇⁠kĕ náşǐym֙ bĕ̇⁠qirĕbé̇֔⁠kĕ lĕ⁠ʼò֣yĕba֔yi⁠kĕ pá̇ţ֥wòẖa nipĕţĕ̇ẖ֖ẇ şǎʻàré֣y ʼarĕẕé֑⁠kĕ ʼákĕlá֥h ʼé֖ş̌ bĕ̇riyẖáֽyi⁠k׃"],[3,14,"מֵ֤י מָצוֹר֙ שַֽׁאֲבִי־לָ֔⁠ךְ חַזְּקִ֖י מִבְצָרָ֑יִ⁠ךְ בֹּ֧אִי בַ⁠טִּ֛יט וְ⁠רִמְסִ֥י בַ⁠חֹ֖מֶר הַחֲזִ֥יקִי מַלְבֵּֽן׃","mé֤y máẕwòr֙ şǎֽʼàbiy-lá֔⁠kĕ ẖazĕ̇qi֖y mibĕẕárá֑yi⁠kĕ bò֧̇ʼiy ba⁠ti֛̇yt wĕ⁠rimĕsi֥y ba⁠ẖò֖mer haẖàzi֥yqiy malĕbéֽ̇n׃"],[3,15,"שָׁ֚ם תֹּאכְלֵ֣⁠ךְ אֵ֔שׁ תַּכְרִיתֵ֣⁠ךְ חֶ֔רֶב תֹּאכְלֵ֖⁠ךְ כַּ⁠יָּ֑לֶק הִתְכַּבֵּ֣ד כַּ⁠יֶּ֔לֶק הִֽתְכַּבְּדִ֖י כָּ⁠אַרְבֶּֽה׃","şá֚̌m ţò̇ʼkĕlé֣⁠kĕ ʼé֔ş̌ ţȧkĕriyţé֣⁠kĕ ẖe֔reb ţò̇ʼkĕlé֖⁠kĕ kȧ⁠yá֑̇leq hiţĕkȧbé֣̇d kȧ⁠yė֔leq hiֽţĕkȧbĕ̇di֖y ká̇⁠ʼarĕbėֽh׃"],[3,16,"הִרְבֵּית֙ רֹֽכְלַ֔יִ⁠ךְ מִ⁠כּוֹכְבֵ֖י הַ⁠שָּׁמָ֑יִם יֶ֥לֶק פָּשַׁ֖ט וַ⁠יָּעֹֽף׃","hirĕbé̇yţ֙ ròֽkĕla֔yi⁠kĕ mi⁠k̇wòkĕbé֖y ha⁠şá̇̌má֑yim ye֥leq pá̇şǎ֖t wa⁠yá̇ʻòֽp׃"],[3,17,"מִנְּזָרַ֨יִ⁠ךְ֙ כָּֽ⁠אַרְבֶּ֔ה וְ⁠טַפְסְרַ֖יִ⁠ךְ כְּ⁠ג֣וֹב גֹּבָ֑י הַֽ⁠חוֹנִ֤ים בַּ⁠גְּדֵרוֹת֙ בְּ⁠י֣וֹם קָרָ֔ה שֶׁ֤מֶשׁ זָֽרְחָה֙ וְ⁠נוֹדַ֔ד וְ⁠לֹֽא־נוֹדַ֥ע מְקוֹמ֖⁠וֹ אַיָּֽ⁠ם׃","minĕ̇zára֨yi⁠kĕ֙ káֽ̇⁠ʼarĕbė֔h wĕ⁠tapĕsĕra֖yi⁠kĕ kĕ̇⁠g֣wòb gò̇bá֑y haֽ⁠ẖwòni֤ym bȧ⁠gĕ̇dérwòţ֙ bĕ̇⁠y֣wòm qárá֔h şě֤meş̌ záֽrĕẖáh֙ wĕ⁠nwòda֔d wĕ⁠lòֽʼ-nwòda֥ʻ mĕqwòm֖⁠wò ʼayáֽ̇⁠m׃"],[3,18,"נָמ֤וּ רֹעֶ֨י⁠ךָ֙ מֶ֣לֶךְ אַשּׁ֔וּר יִשְׁכְּנ֖וּ אַדִּירֶ֑י⁠ךָ נָפֹ֧שׁוּ עַמְּ⁠ךָ֛ עַל־הֶ⁠הָרִ֖ים וְ⁠אֵ֥ין מְקַבֵּֽץ׃","nám֤ẇ ròʻe֨y⁠ká֙ me֣lekĕ ʼaş̇̌֔ẇr yişĕ̌kĕ̇n֖ẇ ʼadi̇yre֑y⁠ká nápò֧ş̌ẇ ʻamĕ̇⁠ká֛ ʻal-he⁠hári֖ym wĕ⁠ʼé֥yn mĕqabéֽ̇ẕ׃"],[3,19,"אֵין־כֵּהָ֣ה לְ⁠שִׁבְרֶ֔⁠ךָ נַחְלָ֖ה מַכָּתֶ֑⁠ךָ כֹּ֣ל ׀ שֹׁמְעֵ֣י שִׁמְעֲ⁠ךָ֗ תָּ֤קְעוּ כַף֙ עָלֶ֔י⁠ךָ כִּ֗י עַל־מִ֛י לֹֽא־עָבְרָ֥ה רָעָתְ⁠ךָ֖ תָּמִֽיד׃","ʼéyn-ké̇há֣h lĕ⁠şǐbĕre֔⁠ká naẖĕlá֖h maká̇ţe֑⁠ká kò֣̇l ׀ şò̌mĕʻé֣y şǐmĕʻà⁠ká֗ ţá֤̇qĕʻẇ kap֙ ʻále֔y⁠ká ki̇֗y ʻal-mi֛y lòֽʼ-ʻábĕrá֥h ráʻáţĕ⁠ká֖ ţá̇miֽyd׃"]],"fra-lsg1910":[[1,1,"Oracle sur Ninive. Livre de la prophétie de Nahum, d'Elkosch.","Oracle sur Ninive. Livre de la prophétie de Nahum, d'Elkosch."],[1,2,"L'Éternel est un Dieu jaloux, il se venge; L'Éternel se venge, il est plein de fureur; L'Éternel se venge de ses adversaires, Il garde rancune à ses ennemis.","L'Éternel est un Dieu jaloux, il se venge; L'Éternel se venge, il est plein de fureur; L'Éternel se venge de ses adversaires, Il garde rancune à ses ennemis."],[1,3,"L'Éternel est lent à la colère, il est grand par sa force; Il ne laisse pas impuni. L'Éternel marche dans la tempête, dans le tourbillon; Les nuées sont la poussière de ses pieds.","L'Éternel est lent à la colère, il est grand par sa force; Il ne laisse pas impuni. L'Éternel marche dans la tempête, dans le tourbillon; Les nuées sont la poussière de ses pieds."],[1,4,"Il menace la mer et la dessèche, Il fait tarir tous les fleuves; Le Basan et le Carmel languissent, La fleur du Liban se flétrit.","Il menace la mer et la dessèche, Il fait tarir tous les fleuves; Le Basan et le Carmel languissent, La fleur du Liban se flétrit."],[1,5,"Les montagnes s'ébranlent devant lui, Et les collines se fondent; La terre se soulève devant sa face, Le monde et tous ses habitants.","Les montagnes s'ébranlent devant lui, Et les collines se fondent; La terre se soulève devant sa face, Le monde et tous ses habitants."],[1,6,"Qui résistera devant sa fureur? Qui tiendra contre son ardente colère? Sa fureur se répand comme le feu, Et les rochers se brisent devant lui.","Qui résistera devant sa fureur? Qui tiendra contre son ardente colère? Sa fureur se répand comme le feu, Et les rochers se brisent devant lui."],[1,7,"L'Éternel est bon, Il est un refuge au jour de la détresse; Il connaît ceux qui se confient en lui.","L'Éternel est bon, Il est un refuge au jour de la détresse; Il connaît ceux qui se confient en lui."],[1,8,"Mais avec des flots qui déborderont Il détruira la ville, Et il poursuivra ses ennemis jusque dans les ténèbres.","Mais avec des flots qui déborderont Il détruira la ville, Et il poursuivra ses ennemis jusque dans les ténèbres."],[1,9,"Que méditez-vous contre l'Éternel? C'est lui qui détruit. La détresse ne paraîtra pas deux fois.","Que méditez-vous contre l'Éternel? C'est lui qui détruit. La détresse ne paraîtra pas deux fois."],[1,10,"Car entrelacés comme des épines, Et comme ivres de leur vin, Ils seront consumés Comme la paille sèche, entièrement.","Car entrelacés comme des épines, Et comme ivres de leur vin, Ils seront consumés Comme la paille sèche, entièrement."],[1,11,"De toi est sorti Celui qui méditait le mal contre l'Éternel, Celui qui avait de méchants desseins.","De toi est sorti Celui qui méditait le mal contre l'Éternel, Celui qui avait de méchants desseins."],[1,12,"Ainsi parle l'Éternel: Quoique intacts et nombreux, Ils seront moissonnés et disparaîtront. Je veux t'humilier, Pour ne plus avoir à t'humilier...","Ainsi parle l'Éternel: Quoique intacts et nombreux, Ils seront moissonnés et disparaîtront. Je veux t'humilier, Pour ne plus avoir à t'humilier..."],[1,13,"Je briserai maintenant son joug de dessus toi, Et je romprai tes liens...","Je briserai maintenant son joug de dessus toi, Et je romprai tes liens..."],[1,14,"Voici ce qu'a ordonné sur toi l'Éternel: Tu n'auras plus de descendants qui portent ton nom; J'enlèverai de la maison de ton dieu les images taillées ou en fonte; Je préparerai ton sépulcre, car tu es trop léger.","Voici ce qu'a ordonné sur toi l'Éternel: Tu n'auras plus de descendants qui portent ton nom; J'enlèverai de la maison de ton dieu les images taillées ou en fonte; Je préparerai ton sépulcre, car tu es trop léger."],[1,15,"Voici sur les montagnes Les pieds du messager qui annonce la paix! Célèbre tes fêtes, Juda, accomplis tes voeux! Car le méchant ne passera plus au milieu de toi, Il est entièrement exterminé...","Voici sur les montagnes Les pieds du messager qui annonce la paix! Célèbre tes fêtes, Juda, accomplis tes voeux! Car le méchant ne passera plus au milieu de toi, Il est entièrement exterminé..."],[2,1,"Le destructeur marche contre toi. Garde la forteresse! Veille sur la route! affermis tes reins! Recueille toute ta force!...","Le destructeur marche contre toi. Garde la forteresse! Veille sur la route! affermis tes reins! Recueille toute ta force!..."],[2,2,"Car l'Éternel rétablit la gloire de Jacob Et la gloire d'Israël, Parce que les pillards les ont pillés Et ont détruit leurs ceps....","Car l'Éternel rétablit la gloire de Jacob Et la gloire d'Israël, Parce que les pillards les ont pillés Et ont détruit leurs ceps...."],[2,3,"Les boucliers de ses héros sont rouges, Les guerriers sont vêtus de pourpre; Avec le fer qui étincelle apparaissent les chars, Au jour qu'il a fixé pour la bataille, Et les lances sont agitées.","Les boucliers de ses héros sont rouges, Les guerriers sont vêtus de pourpre; Avec le fer qui étincelle apparaissent les chars, Au jour qu'il a fixé pour la bataille, Et les lances sont agitées."],[2,4,"Les chars s'élancent dans la campagne, Se précipitent sur les places; À les voir, on dirait des flambeaux, Ils courent comme des éclairs...","Les chars s'élancent dans la campagne, Se précipitent sur les places; À les voir, on dirait des flambeaux, Ils courent comme des éclairs..."],[2,5,"Il se souvient de ses vaillants hommes, Mais ils chancellent dans leur marche; On se hâte vers les murs, Et l'on se prépare à la défense....","Il se souvient de ses vaillants hommes, Mais ils chancellent dans leur marche; On se hâte vers les murs, Et l'on se prépare à la défense...."],[2,6,"Les portes des fleuves sont ouvertes, Et le palais s'écroule!...","Les portes des fleuves sont ouvertes, Et le palais s'écroule!..."],[2,7,"C'en est fait: elle est mise à nu, elle est emmenée; Ses servantes gémissent comme des colombes, Et se frappent la poitrine.","C'en est fait: elle est mise à nu, elle est emmenée; Ses servantes gémissent comme des colombes, Et se frappent la poitrine."],[2,8,"Ninive était jadis comme un réservoir plein d'eau.... Les voilà qui fuient.... Arrêtez! arrêtez!... Mais nul ne se retourne....","Ninive était jadis comme un réservoir plein d'eau.... Les voilà qui fuient.... Arrêtez! arrêtez!... Mais nul ne se retourne...."],[2,9,"Pillez l'argent! pillez l'or! Il y a des trésors sans fin, Des richesses en objets précieux de toute espèce.","Pillez l'argent! pillez l'or! Il y a des trésors sans fin, Des richesses en objets précieux de toute espèce."],[2,10,"On pille, on dévaste, on ravage! Et les coeurs sont abattus, Les genoux chancellent, Tous les reins souffrent, Tous les visages pâlissent.","On pille, on dévaste, on ravage! Et les coeurs sont abattus, Les genoux chancellent, Tous les reins souffrent, Tous les visages pâlissent."],[2,11,"Qu'est devenu ce repaire de lions, Ce pâturage des lionceaux, Où se retiraient le lion, la lionne, le petit du lion, Sans qu'il y eût personne pour les troubler?","Qu'est devenu ce repaire de lions, Ce pâturage des lionceaux, Où se retiraient le lion, la lionne, le petit du lion, Sans qu'il y eût personne pour les troubler?"],[2,12,"Le lion déchirait pour ses petits, Étranglait pour ses lionnes; Il remplissait de proie ses antres, De dépouilles ses repaires.","Le lion déchirait pour ses petits, Étranglait pour ses lionnes; Il remplissait de proie ses antres, De dépouilles ses repaires."],[2,13,"Voici, j'en veux à toi, dit l'Éternel des armées; Je réduirai tes chars en fumée, L'épée dévorera tes lionceaux, J'arracherai du pays ta proie, Et l'on n'entendra plus la voix de tes messagers.","Voici, j'en veux à toi, dit l'Éternel des armées; Je réduirai tes chars en fumée, L'épée dévorera tes lionceaux, J'arracherai du pays ta proie, Et l'on n'entendra plus la voix de tes messagers."],[3,1,"Malheur à la ville sanguinaire, Pleine de mensonge, pleine de violence, Et qui ne cesse de se livrer à la rapine!...","Malheur à la ville sanguinaire, Pleine de mensonge, pleine de violence, Et qui ne cesse de se livrer à la rapine!..."],[3,2,"On entend le bruit du fouet, Le bruit des roues, Le galop des chevaux, Le roulement des chars.","On entend le bruit du fouet, Le bruit des roues, Le galop des chevaux, Le roulement des chars."],[3,3,"Les cavaliers s'élancent, l'épée étincelle, la lance brille... Une multitude de blessés!... une foule de cadavres!... Des morts à l'infini!... On tombe sur les morts!...","Les cavaliers s'élancent, l'épée étincelle, la lance brille... Une multitude de blessés!... une foule de cadavres!... Des morts à l'infini!... On tombe sur les morts!..."],[3,4,"C'est à cause des nombreuses prostitutions de la prostituée, Pleine d'attraits, habile enchanteresse, Qui vendait les nations par ses prostitutions Et les peuples par ses enchantements.","C'est à cause des nombreuses prostitutions de la prostituée, Pleine d'attraits, habile enchanteresse, Qui vendait les nations par ses prostitutions Et les peuples par ses enchantements."],[3,5,"Voici, j'en veux à toi, dit l'Éternel des armées, Je relèverai tes pans jusque sur ton visage, Je montrerai ta nudité aux nations, Et ta honte aux royaumes.","Voici, j'en veux à toi, dit l'Éternel des armées, Je relèverai tes pans jusque sur ton visage, Je montrerai ta nudité aux nations, Et ta honte aux royaumes."],[3,6,"Je jetterai sur toi des impuretés, je t'avilirai, Et je te donnerai en spectacle.","Je jetterai sur toi des impuretés, je t'avilirai, Et je te donnerai en spectacle."],[3,7,"Tous ceux qui te verront fuiront loin de toi, Et l'on dira: Ninive est détruite! Qui la plaindra? Où te chercherai-je des consolateurs?","Tous ceux qui te verront fuiront loin de toi, Et l'on dira: Ninive est détruite! Qui la plaindra? Où te chercherai-je des consolateurs?"],[3,8,"Es-tu meilleure que No-Amon, Qui était assise au milieu des fleuves, Entourée par les eaux, Ayant la mer pour rempart, La mer pour murailles?","Es-tu meilleure que No-Amon, Qui était assise au milieu des fleuves, Entourée par les eaux, Ayant la mer pour rempart, La mer pour murailles?"],[3,9,"L'Éthiopie et les Égyptiens innombrables faisaient sa force, Puth et les Libyens étaient ses auxiliaires.","L'Éthiopie et les Égyptiens innombrables faisaient sa force, Puth et les Libyens étaient ses auxiliaires."],[3,10,"Et cependant elle est partie pour l'exil, elle s'en est allée captive; Ses enfants ont été écrasés au coin de toutes les rues; On a jeté le sort sur ses nobles, Et tous ses grands ont été chargés de chaînes.","Et cependant elle est partie pour l'exil, elle s'en est allée captive; Ses enfants ont été écrasés au coin de toutes les rues; On a jeté le sort sur ses nobles, Et tous ses grands ont été chargés de chaînes."],[3,11,"Toi aussi, tu seras enivrée, tu te cacheras; Toi aussi, tu chercheras un refuge contre l'ennemi.","Toi aussi, tu seras enivrée, tu te cacheras; Toi aussi, tu chercheras un refuge contre l'ennemi."],[3,12,"Toutes tes forteresses Sont des figuiers avec les primeurs; Quand on les secoue, Elles tombent dans la bouche de qui veut les manger.","Toutes tes forteresses Sont des figuiers avec les primeurs; Quand on les secoue, Elles tombent dans la bouche de qui veut les manger."],[3,13,"Voici, ton peuple, ce sont des femmes au milieu de toi; Les portes de ton pays s'ouvrent à tes ennemis; Le feu consume tes verrous.","Voici, ton peuple, ce sont des femmes au milieu de toi; Les portes de ton pays s'ouvrent à tes ennemis; Le feu consume tes verrous."],[3,14,"Puise de l'eau pour le siège! Répare tes forteresses! Entre dans la boue, foule l'argile! Rétablis le four à briques!","Puise de l'eau pour le siège! Répare tes forteresses! Entre dans la boue, foule l'argile! Rétablis le four à briques!"],[3,15,"Là, le feu te dévorera, L'épée t'exterminera, Te dévorera comme des sauterelles. Entasse-toi comme les sauterelles! Entasse-toi comme les sauterelles!","Là, le feu te dévorera, L'épée t'exterminera, Te dévorera comme des sauterelles. Entasse-toi comme les sauterelles! Entasse-toi comme les sauterelles!"],[3,16,"Tes marchands, plus nombreux Que les étoiles du ciel, Sont comme la sauterelle qui ouvre les ailes et s'envole.","Tes marchands, plus nombreux Que les étoiles du ciel, Sont comme la sauterelle qui ouvre les ailes et s'envole."],[3,17,"Tes princes sont comme les sauterelles, Tes chefs comme une multitude de sauterelles, Qui se posent sur les haies au temps de la froidure: Le soleil paraît, elles s'envolent, Et l'on ne connaît plus le lieu où elles étaient.","Tes princes sont comme les sauterelles, Tes chefs comme une multitude de sauterelles, Qui se posent sur les haies au temps de la froidure: Le soleil paraît, elles s'envolent, Et l'on ne connaît plus le lieu où elles étaient."],[3,18,"Tes bergers sommeillent, roi d'Assyrie, Tes vaillants hommes reposent; Ton peuple est dispersé sur les montagnes, Et nul ne le rassemble.","Tes bergers sommeillent, roi d'Assyrie, Tes vaillants hommes reposent; Ton peuple est dispersé sur les montagnes, Et nul ne le rassemble."],[3,19,"Il n'y a point de remède à ta blessure, Ta plaie est mortelle. Tous ceux qui entendront parler de toi Battront des mains sur toi; Car quel est celui que ta méchanceté n'a pas atteint?","Il n'y a point de remède à ta blessure, Ta plaie est mortelle. Tous ceux qui entendront parler de toi Battront des mains sur toi; Car quel est celui que ta méchanceté n'a pas atteint?"]],"spa-rv1909":[[1,1,"CARGAde Nínive. Librode la visiónde Nahumde El-kosh.","CARGAde Nínive. Librode la visiónde Nahumde El-kosh."],[1,2,"Dioscelosoy vengadores Jehová; vengadores Jehová, y Señor de ira; Jehová, que se vengade susadversarios, y que guardaenojopara susenemigos.","Dioscelosoy vengadores Jehová; vengadores Jehová, y Señor de ira; Jehová, que se vengade susadversarios, y que guardaenojopara susenemigos."],[1,3,"Jehováes tardopara la ira, y grandeen poder, y notendráal culpadopor inocente. Jehovámarchaentre la tempestady turbión, y las nubesson el polvode sus pies.","Jehováes tardopara la ira, y grandeen poder, y notendráal culpadopor inocente. Jehovámarchaentre la tempestady turbión, y las nubesson el polvode sus pies."],[1,4,"El amenazaá la mar, y la hace secar, y agostatodoslos ríos: Basánfué destruído, y el Carmelo, y la flordel Líbanofué destruída.","El amenazaá la mar, y la hace secar, y agostatodoslos ríos: Basánfué destruído, y el Carmelo, y la flordel Líbanofué destruída."],[1,5,"Los montestiemblandeél, y los colladosse deslíen; y la tierrase abrasaásu presencia, y el mundo, y todoslos que en él habitan.","Los montestiemblandeél, y los colladosse deslíen; y la tierrase abrasaásu presencia, y el mundo, y todoslos que en él habitan."],[1,6,"¿Quiénpermanecerádelantede su ira? ¿y quiénquedará en piéen el furorde su enojo? Su irase derramacomo fuego, y porél se hiendenlas peñas.","¿Quiénpermanecerádelantede su ira? ¿y quiénquedará en piéen el furorde su enojo? Su irase derramacomo fuego, y porél se hiendenlas peñas."],[1,7,"Buenoes Jehovápara fortalezaen el díade la angustia; y conoceá los que en él confían.","Buenoes Jehovápara fortalezaen el díade la angustia; y conoceá los que en él confían."],[1,8,"Mas con inundaciónimpetuosaharáconsumaciónde su lugar, y tinieblasperseguiráná sus enemigos.","Mas con inundaciónimpetuosaharáconsumaciónde su lugar, y tinieblasperseguiráná sus enemigos."],[1,9,"¿QuépensáiscontraJehová? Elharáconsumación: la tribulaciónnose levantará dosveces.","¿QuépensáiscontraJehová? Elharáconsumación: la tribulaciónnose levantará dosveces."],[1,10,"Porquecomo espinasentretegidas, mientras se embriagaránlos borrachos, serán consumidoscomo las estopasllenasde sequedad.","Porquecomo espinasentretegidas, mientras se embriagaránlos borrachos, serán consumidoscomo las estopasllenasde sequedad."],[1,11,"Deti salióel que pensó malcontraJehová, un consultorimpío.","Deti salióel que pensó malcontraJehová, un consultorimpío."],[1,12,"Asíha dichoJehová: Aunquereposotengan, y sean tantos, asíserán talados, y él pasará. Bien que te he afligido, nomáste afligiré.","Asíha dichoJehová: Aunquereposotengan, y sean tantos, asíserán talados, y él pasará. Bien que te he afligido, nomáste afligiré."],[1,13,"Porque ahoraquebrarésu yugode sobreti, y romperétus coyundas.","Porque ahoraquebrarésu yugode sobreti, y romperétus coyundas."],[1,14,"Mas acercade ti mandaráJehová, que nuncamás sea sembradoalgunode tu nombre: de la casade tu diostalaréesculturay estatuade fundición, harélatu sepulcro; porquefuiste vil.","Mas acercade ti mandaráJehová, que nuncamás sea sembradoalgunode tu nombre: de la casade tu diostalaréesculturay estatuade fundición, harélatu sepulcro; porquefuiste vil."],[1,15,"He aquísobrelos monteslos piesdel que trae buenas nuevas, del que pregona la paz. Celebra, oh Judá, tus fiestas, cumpletus votos: porquenuncamáspasará por ti el malvado; pereciódel todo.","He aquísobrelos monteslos piesdel que trae buenas nuevas, del que pregona la paz. Celebra, oh Judá, tus fiestas, cumpletus votos: porquenuncamáspasará por ti el malvado; pereciódel todo."],[2,1,"SUBIÓdestruidorcontrati: guardala fortaleza, mirael camino, fortificalos lomos, fortalecemuchola fuerza.","SUBIÓdestruidorcontrati: guardala fortaleza, mirael camino, fortificalos lomos, fortalecemuchola fuerza."],[2,2,"PorqueJehovárestituirála gloriade Jacobcomo la gloriade Israel; porquevaciadores los vaciaron, y estropearonsus mugrones.","PorqueJehovárestituirála gloriade Jacobcomo la gloriade Israel; porquevaciadores los vaciaron, y estropearonsus mugrones."],[2,3,"El escudode sus valientesserá bermejo, los varonesde suejércitovestidos de grana: el carrocomo fuegode hachas; el díaque se aparejará, temblaránlas hayas.","El escudode sus valientesserá bermejo, los varonesde suejércitovestidos de grana: el carrocomo fuegode hachas; el díaque se aparejará, temblaránlas hayas."],[2,4,"Los carrosse precipitaráná las plazas, discurriránpor las calles: su aspectocomo hachasencendidas; correráncomo relámpagos.","Los carrosse precipitaráná las plazas, discurriránpor las calles: su aspectocomo hachasencendidas; correráncomo relámpagos."],[2,5,"Acordaráseél de sus valientes; andando tropezarán; se apresuraráná su muro, y la cubiertase aparejará.","Acordaráseél de sus valientes; andando tropezarán; se apresuraráná su muro, y la cubiertase aparejará."],[2,6,"Las puertasde los ríosse abrirán, y el palacioserá destruído.","Las puertasde los ríosse abrirán, y el palacioserá destruído."],[2,7,"Y la reina fué cautiva; mandarle han que suba, y sus criadasla llevarángimiendocomo palomas, batiendosus pechos.","Y la reina fué cautiva; mandarle han que suba, y sus criadasla llevarángimiendocomo palomas, batiendosus pechos."],[2,8,"Y fué Nínivede tiempoantiguo como estanquede aguas; mas elloshuyen: Parad, parad; y ningunomira.","Y fué Nínivede tiempoantiguo como estanquede aguas; mas elloshuyen: Parad, parad; y ningunomira."],[2,9,"Saqueadplata, saqueadoro: nohay finde las riquezasysuntuosidadde todoajuarde codicia.","Saqueadplata, saqueadoro: nohay finde las riquezasysuntuosidadde todoajuarde codicia."],[2,10,"Vacía, y agotada, y despedazadaestá, y el corazónderretido: batimiento de rodillas, y doloren todos riñones, y los rostrosde todos tomarán negrura.","Vacía, y agotada, y despedazadaestá, y el corazónderretido: batimiento de rodillas, y doloren todos riñones, y los rostrosde todos tomarán negrura."],[2,11,"¿Quées de la moradade los leones, y de la majadade los cachorrosde los leones, dondese recogíael león, y la leona, y los cachorrosdel león, y nohabía quien les pusiese miedo?","¿Quées de la moradade los leones, y de la majadade los cachorrosde los leones, dondese recogíael león, y la leona, y los cachorrosdel león, y nohabía quien les pusiese miedo?"],[2,12,"El leónarrebatabaen abundanciapara sus cachorros, y ahogabapara sus leonas, y henchía de presasus cavernas, y de robosus moradas.","El leónarrebatabaen abundanciapara sus cachorros, y ahogabapara sus leonas, y henchía de presasus cavernas, y de robosus moradas."],[2,13,"Heme aquícontrati, diceJehováde los ejércitos. Encenderéy reduciréá humotuscarros, y espadadevorarátus leoncillos; y raeréde la tierratu robo, y nuncamásse oirávozde tus embajadores.","Heme aquícontrati, diceJehováde los ejércitos. Encenderéy reduciréá humotuscarros, y espadadevorarátus leoncillos; y raeréde la tierratu robo, y nuncamásse oirávozde tus embajadores."],[3,1,"¡AYde la ciudadde sangres, todallena de mentiray de rapiña, sinapartarse de ellael pillaje!","¡AYde la ciudadde sangres, todallena de mentiray de rapiña, sinapartarse de ellael pillaje!"],[3,2,"Sonidode látigo, y estruendode movimiento de ruedas; y caballoatropellador, y carrosaltador;","Sonidode látigo, y estruendode movimiento de ruedas; y caballoatropellador, y carrosaltador;"],[3,3,"Caballeroenhiesto, y resplandorde espada, y resplandorde lanza; y multitudde muertos, y multitudde cadáveres; y de sus cadáveresno habrá fin, y en sus cadáverestropezarán:","Caballeroenhiesto, y resplandorde espada, y resplandorde lanza; y multitudde muertos, y multitudde cadáveres; y de sus cadáveresno habrá fin, y en sus cadáverestropezarán:"],[3,4,"A causa de la multitudde las fornicacionesde la ramerade hermosagala, maestrade brujerías, que vendelas gentescon sus fornicaciones, y los puebloscon sus hechizos.","A causa de la multitudde las fornicacionesde la ramerade hermosagala, maestrade brujerías, que vendelas gentescon sus fornicaciones, y los puebloscon sus hechizos."],[3,5,"Heme aquícontrati, diceJehováde los ejércitos, y descubrirétus faldasentu cara, y mostraréá las gentestu desnudez, y á los reinostu vergüenza.","Heme aquícontrati, diceJehováde los ejércitos, y descubrirétus faldasentu cara, y mostraréá las gentestu desnudez, y á los reinostu vergüenza."],[3,6,"Y echarésobreti suciedades, y te afrentaré, y te pondrécomo estiércol.","Y echarésobreti suciedades, y te afrentaré, y te pondrécomo estiércol."],[3,7,"Y será que todoslos que te vieren, se apartarándeti, y dirán: Nínivees asolada: ¿quiénse compadecerá deella? ¿dónde tebuscaréconsoladores?","Y será que todoslos que te vieren, se apartarándeti, y dirán: Nínivees asolada: ¿quiénse compadecerá deella? ¿dónde tebuscaréconsoladores?"],[3,8,"¿Eres tú mejorque No-amón, que estaba asentadaentre ríos, cercada de aguas, cuyobaluarteera la mar, ydel marsu muralla?","¿Eres tú mejorque No-amón, que estaba asentadaentre ríos, cercada de aguas, cuyobaluarteera la mar, ydel marsu muralla?"],[3,9,"Etiopíaera su fortaleza, y Egiptosinlímite; Puty Libiafueronen tu ayuda.","Etiopíaera su fortaleza, y Egiptosinlímite; Puty Libiafueronen tu ayuda."],[3,10,"Tambiénella fuéllevadaen cautiverio: tambiénsuschiquitosfueron estrelladosen las encrucijadasde todaslas calles; y sobresusvaronesecharonsuertes, y todossusmagnatesfueron aprisionadoscon grillos.","Tambiénella fuéllevadaen cautiverio: tambiénsuschiquitosfueron estrelladosen las encrucijadasde todaslas calles; y sobresusvaronesecharonsuertes, y todossusmagnatesfueron aprisionadoscon grillos."],[3,11,"Tútambiénserás embriagada, serásencerrada; tútambiénbuscarásfortalezaá causa del enemigo.","Tútambiénserás embriagada, serásencerrada; tútambiénbuscarásfortalezaá causa del enemigo."],[3,12,"Todastus fortalezascual higuerasconbrevas; que silas sacuden, caenenla bocadel que las ha de comer.","Todastus fortalezascual higuerasconbrevas; que silas sacuden, caenenla bocadel que las ha de comer."],[3,13,"He aquí, tu puebloserácomo mujeresen mediode ti: las puertasde tu tierrase abrirán de paren pará tus enemigos: fuegoconsumirátus barras.","He aquí, tu puebloserácomo mujeresen mediode ti: las puertasde tu tierrase abrirán de paren pará tus enemigos: fuegoconsumirátus barras."],[3,14,"Provéetede aguapara el cerco, fortifica tus fortalezas; entraen el lodo, pisael barro, fortifica el horno.","Provéetede aguapara el cerco, fortifica tus fortalezas; entraen el lodo, pisael barro, fortifica el horno."],[3,15,"Allíte consumiráel fuego, te talarála espada, te devorarácomo pulgón: multiplícatecomo langosta, multiplícatecomo langosta.","Allíte consumiráel fuego, te talarála espada, te devorarácomo pulgón: multiplícatecomo langosta, multiplícatecomo langosta."],[3,16,"Multiplicastetus mercaderesmás que las estrellasdel cielo: el pulgón hizo presa, y voló.","Multiplicastetus mercaderesmás que las estrellasdel cielo: el pulgón hizo presa, y voló."],[3,17,"Tus príncipesserán como langostas, y tus grandescomo langostasde langostasque se sientanen valladosen díade frío: salidoel solse mudan, y nose conoceel lugardonde estuvieron.","Tus príncipesserán como langostas, y tus grandescomo langostasde langostasque se sientanen valladosen díade frío: salidoel solse mudan, y nose conoceel lugardonde estuvieron."],[3,18,"Durmierontus pastores, oh reyde Asiria, reposarontus valientes: tu pueblose derramóporlos montes, y nohay quien lo junte.","Durmierontus pastores, oh reyde Asiria, reposarontus valientes: tu pueblose derramóporlos montes, y nohay quien lo junte."],[3,19,"Nohay curapara tu quebradura; tu heridase encrudeció: todoslos que oyerontu fama, batiránlas manossobreti, porque¿sobrequiénnopasócontinuamentetu malicia?","Nohay curapara tu quebradura; tu heridase encrudeció: todoslos que oyerontu fama, batiránlas manossobreti, porque¿sobrequiénnopasócontinuamentetu malicia?"]],"rus-synodal":[[1,1,"Пророчество о Ниневии; книга видений Наума Елкосеянина.","Proročestvo o Ninevii; kniga videnij Nauma Elkoseânina."],[1,2,"Господь есть Бог ревнитель и мститель; мститель Господь и страшен в гневе: мстит Господь врагам Своим и не пощадит противников Своих.","Gospodʹ estʹ Bog revnitelʹ i mstitelʹ; mstitelʹ Gospodʹ i strašen v gneve: mstit Gospodʹ vragam Svoim i ne poŝadit protivnikov Svoih."],[1,3,"Господь долготерпелив и велик могуществом и не оставляет без наказания; в вихре и в буре шествие Господа, облако – пыль от ног Его.","Gospodʹ dolgoterpeliv i velik moguŝestvom i ne ostavlâet bez nakazaniâ; v vihre i v bure šestvie Gospoda, oblako – pylʹ ot nog Ego."],[1,4,"Запретит Он морю, и оно высыхает, и все реки иссякают; вянет Васан и Кармил, и блекнет цвет на Ливане.","Zapretit On morû, i ono vysyhaet, i vse reki issâkaût; vânet Vasan i Karmil, i bleknet cvet na Livane."],[1,5,"Горы трясутся пред Ним, и холмы тают, и земля колеблется пред лицом Его, и вселенная и все живущие в ней.","Gory trâsutsâ pred Nim, i holmy taût, i zemlâ kolebletsâ pred licom Ego, i vselennaâ i vse živuŝie v nej."],[1,6,"Пред негодованием Его кто устоит? И кто стерпит пламя гнева Его? Гнев Его разливается как огонь; скалы распадаются пред Ним.","Pred negodovaniem Ego kto ustoit? I kto sterpit plamâ gneva Ego? Gnev Ego razlivaetsâ kak ogonʹ; skaly raspadaûtsâ pred Nim."],[1,7,"Благ Господь – убежище в день скорби, и знает надеющихся на Него.","Blag Gospodʹ – ubežiŝe v denʹ skorbi, i znaet nadeûŝihsâ na Nego."],[1,8,"Но всепотопляющим наводнением разрушит до основания Ниневию, и врагов Его постигнет мрак.","No vsepotoplâûŝim navodneniem razrušit do osnovaniâ Nineviû, i vragov Ego postignet mrak."],[1,9,"Что умышляете вы против Господа? Он совершит истребление, и бедствие уже не повторится,","Čto umyšlâete vy protiv Gospoda? On soveršit istreblenie, i bedstvie uže ne povtoritsâ,"],[1,10,"ибо сплетшиеся между собою как терновник и упившиеся как пьяницы, они пожраны будут совершенно, как сухая солома.","ibo spletšiesâ meždu soboû kak ternovnik i upivšiesâ kak pʹânicy, oni požrany budut soveršenno, kak suhaâ soloma."],[1,11,"Из тебя произошел умысливший злое против Господа, составивший совет нечестивый.","Iz tebâ proizošel umyslivšij zloe protiv Gospoda, sostavivšij sovet nečestivyj."],[1,12,"Так говорит Господь: хотя они безопасны и многочисленны, но они будут посечены и исчезнут; а тебя, хотя Я отягощал, более не буду отягощать.","Tak govorit Gospodʹ: hotâ oni bezopasny i mnogočislenny, no oni budut posečeny i isčeznut; a tebâ, hotâ Â otâgoŝal, bolee ne budu otâgoŝatʹ."],[1,13,"И ныне Я сокрушу ярмо его, лежащее на тебе, и узы твои разорву.","I nyne Â sokrušu ârmo ego, ležaŝee na tebe, i uzy tvoi razorvu."],[1,14,"А о тебе, Ассур, Господь определил: не будет более семени с твоим именем; из дома бога твоего истреблю истуканов и кумиров; приготовлю тебе в нем могилу, потому что ты будешь в презрении.","A o tebe, Assur, Gospodʹ opredelil: ne budet bolee semeni s tvoim imenem; iz doma boga tvoego istreblû istukanov i kumirov; prigotovlû tebe v nem mogilu, potomu čto ty budešʹ v prezrenii."],[1,15,"Вот, на горах – стопы благовестника, возвещающего мир: празднуй, Иудея, праздники твои, исполняй обеты твои, ибо не будет более проходить по тебе нечестивый: он совсем уничтожен.","Vot, na gorah – stopy blagovestnika, vozveŝaûŝego mir: prazdnuj, Iudeâ, prazdniki tvoi, ispolnâj obety tvoi, ibo ne budet bolee prohoditʹ po tebe nečestivyj: on sovsem uničtožen."],[2,1,"Поднимается на тебя разрушитель: охраняй твердыни, стереги дорогу, укрепи чресла, собирайся с силами.","Podnimaetsâ na tebâ razrušitelʹ: ohranâj tverdyni, steregi dorogu, ukrepi čresla, sobirajsâ s silami."],[2,2,"Ибо восстановит Господь величие Иакова, как величие Израиля, потому что опустошили их опустошители и виноградные ветви их истребили.","Ibo vosstanovit Gospodʹ veličie Iakova, kak veličie Izrailâ, potomu čto opustošili ih opustošiteli i vinogradnye vetvi ih istrebili."],[2,3,"Щит героев его красен; воины его в одеждах багряных; огнем сверкают колесницы в день приготовления к бою, и лес копьев волнуется.","Ŝit geroev ego krasen; voiny ego v odeždah bagrânyh; ognem sverkaût kolesnicy v denʹ prigotovleniâ k boû, i les kopʹev volnuetsâ."],[2,4,"По улицам несутся колесницы, гремят на площадях; блеск от них, как от огня; сверкают, как молния.","Po ulicam nesutsâ kolesnicy, gremât na ploŝadâh; blesk ot nih, kak ot ognâ; sverkaût, kak molniâ."],[2,5,"Он вызывает храбрых своих, но они спотыкаются на ходу своем; поспешают на стены города, но осада уже устроена.","On vyzyvaet hrabryh svoih, no oni spotykaûtsâ na hodu svoem; pospešaût na steny goroda, no osada uže ustroena."],[2,6,"Речные ворота отворяются, и дворец разрушается.","Rečnye vorota otvorâûtsâ, i dvorec razrušaetsâ."],[2,7,"Решено: она будет обнажена и отведена в плен, и рабыни ее будут стонать как голуби, ударяя себя в грудь.","Rešeno: ona budet obnažena i otvedena v plen, i rabyni ee budut stonatʹ kak golubi, udarââ sebâ v grudʹ."],[2,8,"Ниневия со времени существования своего была как пруд, полный водою, а они бегут. «Стойте, стойте!» Но никто не оглядывается.","Nineviâ so vremeni suŝestvovaniâ svoego byla kak prud, polnyj vodoû, a oni begut. «Stojte, stojte!» No nikto ne oglâdyvaetsâ."],[2,9,"Расхищайте серебро, расхищайте золото! нет конца запасам всякой драгоценной утвари.","Rashiŝajte serebro, rashiŝajte zoloto! net konca zapasam vsâkoj dragocennoj utvari."],[2,10,"Разграблена, опустошена и разорена она, – и тает сердце, колени трясутся; у всех в чреслах сильная боль, и лица у всех потемнели.","Razgrablena, opustošena i razorena ona, – i taet serdce, koleni trâsutsâ; u vseh v čreslah silʹnaâ bolʹ, i lica u vseh potemneli."],[2,11,"Где теперь логовище львов и то пастбище для львят, по которому ходил лев, львица и львенок, и никто не пугал их, –","Gde teperʹ logoviŝe lʹvov i to pastbiŝe dlâ lʹvât, po kotoromu hodil lev, lʹvica i lʹvenok, i nikto ne pugal ih, –"],[2,12,"лев, похищающий для насыщения щенков своих, и задушающий для львиц своих, и наполняющий добычею пещеры свои и логовища свои похищенным?","lev, pohiŝaûŝij dlâ nasyŝeniâ ŝenkov svoih, i zadušaûŝij dlâ lʹvic svoih, i napolnâûŝij dobyčeû peŝery svoi i logoviŝa svoi pohiŝennym?"],[2,13,"Вот, Я – на тебя! говорит Господь Саваоф. И сожгу в дыму колесницы твои, и меч пожрет львят твоих, и истреблю с земли добычу твою, и не будет более слышим голос послов твоих.","Vot, Â – na tebâ! govorit Gospodʹ Savaof. I sožgu v dymu kolesnicy tvoi, i meč požret lʹvât tvoih, i istreblû s zemli dobyču tvoû, i ne budet bolee slyšim golos poslov tvoih."],[3,1,"Горе городу кровей! весь он полон обмана и убийства; не прекращается в нем грабительство.","Gore gorodu krovej! vesʹ on polon obmana i ubijstva; ne prekraŝaetsâ v nem grabitelʹstvo."],[3,2,"Слышны хлопанье бича и стук крутящихся колес, ржание коня и грохот скачущей колесницы.","Slyšny hlopanʹe biča i stuk krutâŝihsâ koles, ržanie konâ i grohot skačuŝej kolesnicy."],[3,3,"Несется конница, сверкает меч, и блестят копья; убитых множество и груды трупов: нет конца трупам, спотыкаются о трупы их.","Nesetsâ konnica, sverkaet meč, i blestât kopʹâ; ubityh množestvo i grudy trupov: net konca trupam, spotykaûtsâ o trupy ih."],[3,4,"Это – за многие блудодеяния развратницы приятной наружности, искусной в чародеянии, которая блудодеяниями своими продает народы и чарованиями своими – племена.","Éto – za mnogie bludodeâniâ razvratnicy priâtnoj naružnosti, iskusnoj v čarodeânii, kotoraâ bludodeâniâmi svoimi prodaet narody i čarovaniâmi svoimi – plemena."],[3,5,"Вот, Я – на тебя! говорит Господь Саваоф. И подниму на лицо твое края одежды твоей и покажу народам наготу твою и царствам срамоту твою.","Vot, Â – na tebâ! govorit Gospodʹ Savaof. I podnimu na lico tvoe kraâ odeždy tvoej i pokažu narodam nagotu tvoû i carstvam sramotu tvoû."],[3,6,"И забросаю тебя мерзостями, сделаю тебя презренною и выставлю тебя на позор.","I zabrosaû tebâ merzostâmi, sdelaû tebâ prezrennoû i vystavlû tebâ na pozor."],[3,7,"И будет то, что всякий, увидев тебя, побежит от тебя и скажет: «разорена Ниневия! Кто пожалеет о ней? где найду я утешителей для тебя?»","I budet to, čto vsâkij, uvidev tebâ, pobežit ot tebâ i skažet: «razorena Nineviâ! Kto požaleet o nej? gde najdu â utešitelej dlâ tebâ?»"],[3,8,"Разве ты лучше Но-Аммона, находящегося между реками, окруженного водою, которого вал было море и море служило стеною его?","Razve ty lučše No-Ammona, nahodâŝegosâ meždu rekami, okružennogo vodoû, kotorogo val bylo more i more služilo stenoû ego?"],[3,9,"Ефиопия и Египет с бесчисленным множеством других служили ему подкреплением; Копты и Ливийцы приходили на помощь тебе.","Efiopiâ i Egipet s besčislennym množestvom drugih služili emu podkrepleniem; Kopty i Livijcy prihodili na pomoŝʹ tebe."],[3,10,"Но и он переселен, пошел в плен; даже и младенцы его разбиты на перекрестках всех улиц, а о знатных его бросали жребий, и все вельможи его окованы цепями.","No i on pereselen, pošel v plen; daže i mladency ego razbity na perekrestkah vseh ulic, a o znatnyh ego brosali žrebij, i vse velʹmoži ego okovany cepâmi."],[3,11,"Так и ты – опьянеешь и скроешься; так и ты будешь искать защиты от неприятеля.","Tak i ty – opʹâneešʹ i skroešʹsâ; tak i ty budešʹ iskatʹ zaŝity ot nepriâtelâ."],[3,12,"Все укрепления твои подобны смоковнице со спелыми плодами: если тряхнуть их, то они упадут прямо в рот желающего есть.","Vse ukrepleniâ tvoi podobny smokovnice so spelymi plodami: esli trâhnutʹ ih, to oni upadut prâmo v rot želaûŝego estʹ."],[3,13,"Вот, и народ твой, как женщины у тебя: врагам твоим настежь отворятся ворота земли твоей, огонь пожрет запоры твои.","Vot, i narod tvoj, kak ženŝiny u tebâ: vragam tvoim nastežʹ otvorâtsâ vorota zemli tvoej, ogonʹ požret zapory tvoi."],[3,14,"Начерпай воды на время осады; укрепляй крепости твои; пойди в грязь, топчи глину, исправь печь для обжигания кирпичей.","Načerpaj vody na vremâ osady; ukreplâj kreposti tvoi; pojdi v grâzʹ, topči glinu, ispravʹ pečʹ dlâ obžiganiâ kirpičej."],[3,15,"Там пожрет тебя огонь, посечет тебя меч, поест тебя, как гусеница, хотя бы ты умножился, как гусеница, умножился, как саранча.","Tam požret tebâ ogonʹ, posečet tebâ meč, poest tebâ, kak gusenica, hotâ by ty umnožilsâ, kak gusenica, umnožilsâ, kak saranča."],[3,16,"Купцов у тебя стало более, нежели звезд на небе; но эта саранча рассеется и улетит.","Kupcov u tebâ stalo bolee, neželi zvezd na nebe; no éta saranča rasseetsâ i uletit."],[3,17,"Князья твои – как саранча, и военачальники твои – как рои мошек, которые во время холода гнездятся в щелях стен, и когда взойдет солнце, то разлетаются, и не узнаешь места, где они были.","Knâzʹâ tvoi – kak saranča, i voenačalʹniki tvoi – kak roi mošek, kotorye vo vremâ holoda gnezdâtsâ v ŝelâh sten, i kogda vzojdet solnce, to razletaûtsâ, i ne uznaešʹ mesta, gde oni byli."],[3,18,"Спят пастыри твои, царь Ассирийский, покоятся вельможи твои; народ твой рассеялся по горам, и некому собрать его.","Spât pastyri tvoi, carʹ Assirijskij, pokoâtsâ velʹmoži tvoi; narod tvoj rasseâlsâ po goram, i nekomu sobratʹ ego."],[3,19,"Нет врачевства для раны твоей, болезненна язва твоя. Все, услышавшие весть о тебе, будут рукоплескать о тебе, ибо на кого не простиралась беспрестанно злоба твоя?","Net vračevstva dlâ rany tvoej, boleznenna âzva tvoâ. Vse, uslyšavšie vestʹ o tebe, budut rukopleskatʹ o tebe, ibo na kogo ne prostiralasʹ besprestanno zloba tvoâ?"]],"cmn-cuv-hant":[[1,1,"論 尼尼微的默示，就是 伊勒歌斯人 那鴻所得的默示。","lùn ní ní wēi de mò shì， jiù shì yī lēi gē sī rén nà hóng suǒ dé de mò shì."],[1,2,"耶和華是忌邪施報的神。 耶和華施報大有忿怒； 向他的敵人施報， 向他的仇敵懷怒。","yé hé huá shì jì xié shī bào de shén. yé hé huá shī bào dà yǒu fèn nù； xiàng tā de dí rén shī bào， xiàng tā de chóu dí huái nù."],[1,3,"耶和華不輕易發怒，大有能力， 萬不以 有罪的為無罪。 他乘旋風和暴風而來， 雲彩為他腳下的塵土。","yé hé huá bù qīng yì fā nù， dà yǒu néng lì， wàn bù yǐ yǒu zuì de wèi wú zuì. tā chéng xuán fēng hé bào fēng ér lái， yún cǎi wèi tā jiǎo xià de chén tǔ."],[1,4,"他斥責海，使海乾了， 使一切江河乾涸。 巴珊和 迦密 的樹林衰殘； 黎巴嫩的花草也衰殘了。","tā chì zé hǎi， shǐ hǎi qián le， shǐ yī qiè jiāng hé qián hé. bā shān hé jiā mì de shù lín shuāi cán； lí bā nèn de huā cǎo yě shuāi cán le."],[1,5,"大山因他震動； 小山也都消化。 大地在他面前突起； 世界和住在其間的也都如此。","dà shān yīn tā zhèn dòng； xiǎo shān yě dōu xiāo huà. dà de zài tā miàn qián tū qǐ； shì jiè hé zhù zài qí jiān de yě dōu rú cǐ."],[1,6,"他發忿恨，誰能立得住呢？ 他發烈怒，誰能當得起呢？ 他的忿怒如火傾倒； 磐石因他崩裂。","tā fā fèn hèn， shuí néng lì dé zhù ne？ tā fā liè nù， shuí néng dāng dé qǐ ne？ tā de fèn nù rú huǒ qīng dào； pán shí yīn tā bēng liè."],[1,7,"耶和華本為善， 在患難的日子為人的保障， 並且認得那些投靠他的人。","yé hé huá běn wèi shàn， zài huàn nán de rì zǐ wèi rén de bǎo zhàng， bìng qiě rèn dé nà xiē tóu kào tā de rén."],[1,8,"但他必以漲溢的洪水淹沒 尼尼微， 又驅逐仇敵進入黑暗。","dàn tā bì yǐ zhǎng yì de hóng shuǐ yān méi ní ní wēi， yòu qū zhú chóu dí jìn rù hēi àn."],[1,9,"尼尼微人哪，設何謀攻擊耶和華呢？ 他必 將你們滅絕淨盡； 災難不再興起。","ní ní wēi rén nǎ， shè hé móu gōng jī yé hé huá ne？ tā bì jiāng nǐ men miè jué jìng jǐn； zāi nán bù zài xìng qǐ."],[1,10,"你們像叢雜的荊棘， 像喝醉了的人， 又如枯乾的碎詡全然燒滅。","nǐ men xiàng cóng zá de jīng jí， xiàng hē zuì le de rén， yòu rú kū qián de suì xǔ quán rán shāo miè."],[1,11,"有一人從你那裏出來， 圖謀邪惡，設惡計攻擊耶和華。","yǒu yī rén cóng nǐ nà lǐ chū lái， tú móu xié è， shè è jì gōng jī yé hé huá."],[1,12,"耶和華如此說： 尼尼微雖然勢力充足，人數繁多， 也被剪除，歸於無有。 猶大啊，我雖然使你受苦， 卻不再使你受苦。","yé hé huá rú cǐ shuō： ní ní wēi suī rán shì lì chōng zú， rén shù fán duō， yě bèi jiǎn chú， guī yú wú yǒu. yóu dà a， wǒ suī rán shǐ nǐ shòu kǔ， què bù zài shǐ nǐ shòu kǔ."],[1,13,"現在我必從你 頸項上折斷他的軛， 扭開他的繩索。","xiàn zài wǒ bì cóng nǐ jǐng xiàng shàng zhé duàn tā de è， niǔ kāi tā de shéng suǒ."],[1,14,"耶和華已經出令，指着 尼尼微說： 你名下的人必不留後； 我必從你神的廟中除滅雕刻的偶像和鑄造的偶像； 我必因你鄙陋，使你歸於墳墓。","yé hé huá yǐ jīng chū lìng， zhǐ zhe ní ní wēi shuō： nǐ míng xià de rén bì bù liú hòu； wǒ bì cóng nǐ shén de miào zhōng chú miè diāo kè de ǒu xiàng hé zhù zào de ǒu xiàng； wǒ bì yīn nǐ bǐ lòu， shǐ nǐ guī yú fén mù."],[1,15,"看哪，有報好信傳平安之人的腳登山， 說： 猶大啊，可以守你的節期， 還你所許的願吧！ 因為那惡人不再從你中間經過， 他已滅絕淨盡了。","kàn nǎ， yǒu bào hǎo xìn chuán píng ān zhī rén de jiǎo dēng shān， shuō： yóu dà a， kě yǐ shǒu nǐ de jié qī， hái nǐ suǒ xǔ de yuàn ba！ yīn wèi nà è rén bù zài cóng nǐ zhōng jiān jīng guò， tā yǐ miè jué jìng jǐn le."],[2,1,"尼尼微啊，那打碎 邦國的上來攻擊你。 你要看守保障，謹防道路， 使腰強壯，大大勉力。 （","ní ní wēi a， nà dǎ suì bāng guó de shàng lái gōng jī nǐ. nǐ yào kàn shǒu bǎo zhàng， jǐn fáng dào lù， shǐ yāo qiáng zhuàng， dà dà miǎn lì. （"],[2,2,"耶和華復興 雅各的榮華， 好像 以色列的榮華一樣； 因為使地空虛的， 已經使 雅各和 以色列空虛， 將他們的葡萄枝毀壞了。）","yé hé huá fù xìng yǎ gè de róng huá， hǎo xiàng yǐ sè liè de róng huá yī yàng； yīn wèi shǐ de kōng xū de， yǐ jīng shǐ yǎ gè hé yǐ sè liè kōng xū， jiāng tā men de pú táo zhī huǐ huài le.）"],[2,3,"他勇士的盾牌是紅的， 精兵都穿朱紅 衣服。 在他預備 爭戰的日子， 戰車上的鋼鐵閃爍如火， 柏木把的 槍也掄起來了。","tā yǒng shì de dùn pái shì hóng de， jīng bīng dōu chuān zhū hóng yī fú. zài tā yù bèi zhēng zhàn de rì zǐ， zhàn chē shàng de gāng tiě shǎn shuò rú huǒ， bǎi mù bǎ de qiāng yě lūn qǐ lái le."],[2,4,"車輛在街上急行， 在寬闊處奔來奔去， 形狀如火把， 飛跑如閃電。","chē liàng zài jiē shàng jí xíng， zài kuān kuò chù bēn lái bēn qù， xíng zhuàng rú huǒ bǎ， fēi pǎo rú shǎn diàn."],[2,5,"尼尼微王招聚他的貴冑； 他們步行絆跌， 速上城牆，預備擋牌。","ní ní wēi wáng zhāo jù tā de guì zhòu； tā men bù xíng bàn diē， sù shàng chéng qiáng， yù bèi dǎng pái."],[2,6,"河閘開放，宮殿沖沒。","hé zhá kāi fàng， gōng diàn chōng méi."],[2,7,"王后蒙羞，被人擄去； 宮女搥胸，哀鳴如鴿。 此乃命定之事。","wáng hòu méng xiū， bèi rén lǔ qù； gōng nǚ chuí xiōng， āi míng rú gē. cǐ nǎi mìng dìng zhī shì."],[2,8,"尼尼微自古以來 充滿人民， 如同聚水的池子； 現在居民卻都逃跑。 雖有人呼喊說：站住！站住！ 卻無人回顧。","ní ní wēi zì gǔ yǐ lái chōng mǎn rén mín， rú tóng jù shuǐ de chí zǐ； xiàn zài jū mín què dōu táo pǎo. suī yǒu rén hū hǎn shuō： zhàn zhù！ zhàn zhù！ què wú rén huí gù."],[2,9,"你們搶掠金銀吧！ 因為所積蓄的無窮， 華美的寶器無數。","nǐ men qiǎng lüè jīn yín ba！ yīn wèi suǒ jī xù de wú qióng， huá měi de bǎo qì wú shù."],[2,10,"尼尼微現在空虛荒涼， 人心消化，雙膝相碰， 腰都疼痛，臉都變色。","ní ní wēi xiàn zài kōng xū huāng liáng， rén xīn xiāo huà， shuāng xī xiāng pèng， yāo dōu téng tòng， liǎn dōu biàn sè."],[2,11,"獅子的洞和少壯獅子餵養之處在哪裏呢？ 公獅母獅小獅遊行、無人驚嚇之地在哪裏呢？","shī zǐ de dòng hé shǎo zhuàng shī zǐ wèi yǎng zhī chù zài nǎ lǐ ne？ gōng shī mǔ shī xiǎo shī yóu xíng, wú rén jīng xià zhī de zài nǎ lǐ ne？"],[2,12,"公獅為小獅撕碎許多食物， 為母獅掐死活物， 把撕碎的、掐死的充滿牠的洞穴。","gōng shī wèi xiǎo shī sī suì xǔ duō shí wù， wèi mǔ shī qiā sǐ huó wù， bǎ sī suì de, qiā sǐ de chōng mǎn tā de dòng xué."],[2,13,"萬軍之耶和華說：「我與你為敵，必將你的車輛焚燒成煙，刀劍也必吞滅你的少壯獅子。我必從地上除滅你所撕碎的，你使者的聲音必不再聽見。」","wàn jūn zhī yé hé huá shuō：‘wǒ yǔ nǐ wèi dí， bì jiāng nǐ de chē liàng fén shāo chéng yān， dāo jiàn yě bì tūn miè nǐ de shǎo zhuàng shī zǐ. wǒ bì cóng de shàng chú miè nǐ suǒ sī suì de， nǐ shǐ zhě de shēng yīn bì bù zài tīng jiàn.’"],[3,1,"禍哉！這流人血的城， 充滿謊詐和強暴－ 搶奪的事總不止息。","huò zāi！ zhè liú rén xuè de chéng， chōng mǎn huǎng zhà hé qiáng bào－ qiǎng duó de shì zǒng bù zhǐ xī."],[3,2,"鞭聲響亮，車輪轟轟， 馬匹踢跳，車輛奔騰，","biān shēng xiǎng liàng， chē lún hōng hōng， mǎ pǐ tī tiào， chē liàng bēn téng，"],[3,3,"馬兵爭先，刀劍發光， 槍矛閃爍，被殺的甚多， 屍首成了大堆， 屍骸無數，人碰着而跌倒，","mǎ bīng zhēng xiān， dāo jiàn fā guāng， qiāng máo shǎn shuò， bèi shā de shèn duō， shī shǒu chéng le dà duī， shī hái wú shù， rén pèng zhe ér diē dào，"],[3,4,"都因那美貌的妓女多有淫行， 慣行邪術，藉淫行誘惑列國， 用邪術誘惑多族。","dōu yīn nà měi mào de jì nǚ duō yǒu yín xíng， guàn xíng xié shù， jí yín xíng yòu huò liè guó， yòng xié shù yòu huò duō zú."],[3,5,"萬軍之耶和華說：我與你為敵； 我必揭起你的衣襟，蒙在你臉上， 使列國看見你的赤體， 使列邦觀看你的醜陋。","wàn jūn zhī yé hé huá shuō： wǒ yǔ nǐ wèi dí； wǒ bì jiē qǐ nǐ de yī jīn， méng zài nǐ liǎn shàng， shǐ liè guó kàn jiàn nǐ de chì tǐ， shǐ liè bāng guān kàn nǐ de chǒu lòu."],[3,6,"我必將可憎污穢之物拋在你身上， 辱沒你，為眾目所觀。","wǒ bì jiāng kě zēng wū huì zhī wù pāo zài nǐ shēn shàng， rǔ méi nǐ， wèi zhòng mù suǒ guān."],[3,7,"凡看見你的，都必逃跑離開你， 說： 尼尼微荒涼了！有誰為你悲傷呢？ 我何處尋得安慰你的人呢？","fán kàn jiàn nǐ de， dōu bì táo pǎo lí kāi nǐ， shuō： ní ní wēi huāng liáng le！ yǒu shuí wèi nǐ bēi shāng ne？ wǒ hé chù xún dé ān wèi nǐ de rén ne？"],[3,8,"你豈比 挪亞們強呢？ 挪亞們坐落在眾河之間，周圍有水； 海作她的濠溝， 又作她的城牆。","nǐ qǐ bǐ nuó yà men qiáng ne？ nuó yà men zuò luò zài zhòng hé zhī jiān， zhōu wéi yǒu shuǐ； hǎi zuò tā de háo gōu， yòu zuò tā de chéng qiáng."],[3,9,"古實和 埃及是她無窮的力量； 弗人和 路比族是她的幫手。","gǔ shí hé āi jí shì tā wú qióng de lì liàng； fú rén hé lù bǐ zú shì tā de bāng shǒu."],[3,10,"但她被遷移，被擄去； 她的嬰孩在各市口上也被摔死。 人為她的尊貴人拈鬮； 她所有的大人都被鍊子鎖着。","dàn tā bèi qiān yí， bèi lǔ qù； tā de yīng hái zài gè shì kǒu shàng yě bèi shuāi sǐ. rén wèi tā de zūn guì rén niān jiū； tā suǒ yǒu de dà rén dōu bèi liàn zǐ suǒ zhe."],[3,11,"你也必喝醉，必被埋藏， 並因仇敵的緣故尋求避難所。","nǐ yě bì hē zuì， bì bèi mái cáng， bìng yīn chóu dí de yuán gù xún qiú bì nán suǒ."],[3,12,"你一切保障必像無花果樹上初熟的無花果， 若一搖撼就落在想吃之人的口中。","nǐ yī qiè bǎo zhàng bì xiàng wú huā guǒ shù shàng chū shú de wú huā guǒ， ruò yī yáo hàn jiù luò zài xiǎng chī zhī rén de kǒu zhōng."],[3,13,"你地上的人民如同婦女； 你國中的關口向仇敵敞開； 你的門閂被火焚燒。","nǐ de shàng de rén mín rú tóng fù nǚ； nǐ guó zhōng de guān kǒu xiàng chóu dí chǎng kāi； nǐ de mén shuān bèi huǒ fén shāo."],[3,14,"你要打水預備受困； 要堅固你的保障， 踹土和泥，修補磚窯。","nǐ yào dǎ shuǐ yù bèi shòu kùn； yào jiān gù nǐ de bǎo zhàng， chuài tǔ hé ní， xiū bǔ zhuān yáo."],[3,15,"在那裏，火必燒滅你； 刀必殺戮你， 吞滅你如同蝻子。 任你加增人數多如蝻子， 多如蝗蟲吧！","zài nà lǐ， huǒ bì shāo miè nǐ； dāo bì shā lù nǐ， tūn miè nǐ rú tóng nǎn zǐ. rèn nǐ jiā zēng rén shù duō rú nǎn zǐ， duō rú huáng chóng ba！"],[3,16,"你增添商賈，多過天上的星； 蝻子吃盡而去。","nǐ zēng tiān shāng jiǎ， duō guò tiān shàng de xīng； nǎn zǐ chī jǐn ér qù."],[3,17,"你的首領多如蝗蟲； 你的軍長彷彿成群的螞蚱， 天涼的時候齊落在籬笆上， 日頭一出便都飛去， 人不知道落在何處。","nǐ de shǒu lǐng duō rú huáng chóng； nǐ de jūn zhǎng páng fú chéng qún de mǎ zhà， tiān liáng de shí hòu qí luò zài lí bā shàng， rì tóu yī chū biàn dōu fēi qù， rén bù zhī dào luò zài hé chù."],[3,18,"亞述王啊，你的牧人睡覺； 你的貴冑安歇； 你的人民散在山間，無人招聚。","yà shù wáng a， nǐ de mù rén shuì jué； nǐ de guì zhòu ān xiē； nǐ de rén mín sàn zài shān jiān， wú rén zhāo jù."],[3,19,"你的損傷無法醫治； 你的傷痕極其重大。 凡聽你信息的必都因此向你拍掌。 你所行的惡誰沒有時常遭遇呢？","nǐ de sǔn shāng wú fǎ yī zhì； nǐ de shāng hén jí qí zhòng dà. fán tīng nǐ xìn xī de bì dōu yīn cǐ xiàng nǐ pāi zhǎng. nǐ suǒ xíng de è shuí méi yǒu shí cháng zāo yù ne？"]],"arb-vandyck":[[1,1,"وَحْيٌ عَلَى نِينَوَى. سِفْرُ رُؤْيَا نَاحُومَ ٱلْأَلْقُوشِيِّ.","waḥ̊yuⁿ ʿalay̱ nīnaway̱. sif̊ru rū̊̉yā nāḥūma ٱl̊ạảl̊qūsẖīĩ."],[1,2,"اَلرَّبُّ إِلَهٌ غَيُورٌ وَمُنْتَقِمٌ. ٱلرّبُّ مُنْتَقِمٌ وَذُو سَخَطٍ. ٱلرّبُّ مُنْتَقِمٌ مِن مُبْغِضِيهِ وَحَافِظٌ غَضَبَهُ عَلَى أَعْدَائِهِ.","ạalrãbũ ại̹lahuⁿ gẖayūruⁿ wamun̊taqimuⁿ. ٱlr̃bũ mun̊taqimuⁿ wadẖū sakẖaṭiⁿ. ٱlr̃bũ mun̊taqimuⁿ min mub̊gẖiḍīhi waḥāfiẓuⁿ gẖaḍabahu ʿalay̱ ạảʿ̊dāyỉhi."],[1,3,"ٱلرَّبُّ بَطِيءُ ٱلْغَضَبِ وَعَظِيمُ ٱلْقُدْرَةِ، وَلَكِنَّهُ لَا يُبَرِّئُ ٱلْبَتَّةَ. ٱلرَّبُّ فِي ٱلزَّوْبَعَةِ، وَفِي ٱلْعَاصِفِ طَرِيقُهُ، وَٱلسَّحَابُ غُبَارُ رِجْلَيْهِ.","ٱlrãbũ baṭīʾu ٱl̊gẖaḍabi waʿaẓīmu ٱl̊qud̊raẗi, walakinãhu lā yubarĩyủ ٱl̊batãẗa. ٱlrãbũ fī ٱlzãẘbaʿaẗi, wafī ٱl̊ʿāṣifi ṭarīquhu, waٱlsãḥābu gẖubāru rij̊laẙhi."],[1,4,"يَنْتَهِرُ ٱلْبَحْرَ فَيُنَشِّفُهُ وَيُجَفِّفُ جَمِيعَ ٱلْأَنْهَارِ. يَذْبُلُ بَاشَانُ وَٱلْكَرْمَلُ، وَزَهْرُ لُبْنَانَ يَذْبُلُ.","yan̊tahiru ٱl̊baḥ̊ra fayunasẖĩfuhu wayujafĩfu jamīʿa ٱl̊ạản̊hāri. yadẖ̊bulu bāsẖānu waٱl̊kar̊malu, wazah̊ru lub̊nāna yadẖ̊bulu."],[1,5,"اَلْجِبَالُ تَرْجُفُ مِنْهُ، وَٱلتِّلَالُ تَذُوبُ، وَٱلْأَرْضُ تُرْفَعُ مِنْ وَجْهِهِ، وَٱلْعَالَمُ وَكُلُّ ٱلسَّاكِنِينَ فِيهِ.","ạal̊jibālu tar̊jufu min̊hu, waٱltĩlālu tadẖūbu, waٱl̊ạảr̊ḍu tur̊faʿu min̊ waj̊hihi, waٱl̊ʿālamu wakulũ ٱlsãạkinīna fīhi."],[1,6,"مَنْ يَقِفُ أَمَامَ سَخَطِهِ؟ وَمَنْ يَقُومُ فِي حُمُوِّ غَضَبِهِ؟ غَيْظُهُ يَنْسَكِبُ كَٱلنَّارِ، وَٱلصُّخُورُ تَنْهَدِمُ مِنْهُ.","man̊ yaqifu ạảmāma sakẖaṭihi? waman̊ yaqūmu fī ḥumūĩ gẖaḍabihi? gẖaẙẓuhu yan̊sakibu kaٱlnãạri, waٱlṣũkẖūru tan̊hadimu min̊hu."],[1,7,"صَالِحٌ هُوَ ٱلرَّبُّ. حِصْنٌ فِي يَوْمِ ٱلضَّيقِ، وَهُوَ يَعْرِفُ ٱلْمُتَوَكِّلِينَ عَلَيْهِ.","ṣāliḥuⁿ hūa ٱlrãbũ. ḥiṣ̊nuⁿ fī yaẘmi ٱlḍãyqi, wahūa yaʿ̊rifu ٱl̊mutawakĩlīna ʿalaẙhi."],[1,8,"وَلَكِنْ بِطُوفَانٍ عَابِرٍ يَصْنَعُ هَلَاكًا تَامًّا لِمَوْضِعِهَا، وَأَعْدَاؤُهُ يَتْبَعُهُمْ ظَلَامٌ.","walakin̊ biṭūfāniⁿ ʿābiriⁿ yaṣ̊naʿu halākaⁿạ tāmaⁿ̃ạ limaẘḍiʿihā, wāảʿ̊dāwủhu yat̊baʿuhum̊ ẓalāmuⁿ."],[1,9,"مَاذَا تَفْتَكِرُونَ عَلَى ٱلرَّبِّ؟ هُوَ صَانِعٌ هَلَاكًا تَامًّا. لَا يَقُومُ ٱلضِّيقُ مَرَّتَيْنِ.","mādẖā taf̊takirūna ʿalay̱ ٱlrãbĩ? hūa ṣāniʿuⁿ halākaⁿạ tāmaⁿ̃ạ. lā yaqūmu ٱlḍĩyqu marãtaẙni."],[1,10,"فَإِنَّهُمْ وَهُمْ مُشْتَبِكُونَ مِثْلَ ٱلشَّوْكِ، وَسَكْرَانُونَ كَمِنْ خَمْرِهِمْ، يُؤْكَلُونَ كَٱلْقَشِّ ٱلْيَابِسِ بِٱلْكَمَالِ.","fāi̹nãhum̊ wahum̊ musẖ̊tabikūna mitẖ̊la ٱlsẖãẘki, wasak̊rānūna kamin̊ kẖam̊rihim̊, yū̊̉kalūna kaٱl̊qasẖĩ ٱl̊yābisi biٱl̊kamāli."],[1,11,"مِنْكِ خَرَجَ ٱلْمُفْتَكِرُ عَلَى ٱلرَّبِّ شَرًّا، ٱلْمُشِيرُ بِٱلْهَلَاكِ.","min̊ki kẖaraja ٱl̊muf̊takiru ʿalay̱ ٱlrãbĩ sẖaraⁿ̃ạ, ٱl̊musẖīru biٱl̊halāki."],[1,12,"هَكَذَا قَالَ ٱلرَّبُّ: «إِنْ كَانُوا سَالِمِينَ وَكَثِيرِينَ هَكَذَا، فَهَكَذَا يُجَزُّونَ فَيَعْبُرُ. أَذْلَلْتُكِ. لَا أُذِلُّكِ ثَانِيَةً.","hakadẖā qāla ٱlrãbũ: «ại̹n̊ kānūạ sālimīna wakatẖīrīna hakadẖā, fahakadẖā yujazũwna fayaʿ̊buru. ạảdẖ̊lal̊tuki. lā ạủdẖilũki tẖānīaẗaⁿ."],[1,13,"وَٱلْآنَ أَكْسِرُ نِيرَهُ عَنْكِ وَأَقْطَعُ رُبُطَكِ».","waٱl̊ậna ạảk̊siru nīrahu ʿan̊ki wāảq̊ṭaʿu rubuṭaki»."],[1,14,"وَلَكِنْ قَدْ أَوْصَى عَنْكَ ٱلرَّبُّ: «لَا يُزْرَعُ مِنِ ٱسْمِكَ فِي مَا بَعْدُ. إِنِّي أَقْطَعُ مِنْ بَيْتِ إِلَهِكَ ٱلتَّمَاثِيلَ ٱلْمَنْحُوتَةَ وَٱلْمَسْبُوكَةَ. أَجْعَلُهُ قَبْرَكَ، لِأَنَّكَ صِرْتَ حَقِيرًا».","walakin̊ qad̊ ạảẘṣay̱ ʿan̊ka ٱlrãbũ: «lā yuz̊raʿu mini ٱs̊mika fī mā baʿ̊du. ại̹nĩy ạảq̊ṭaʿu min̊ baẙti ại̹lahika ٱltãmātẖīla ٱl̊man̊ḥūtaẗa waٱl̊mas̊būkaẗa. ạảj̊ʿaluhu qab̊raka, liạảnãka ṣir̊ta ḥaqīraⁿạ»."],[1,15,"هُوَذَا عَلَى ٱلْجِبَالِ قَدَمَا مُبَشِّرٍ مُنَادٍ بِٱلسَّلَامِ! عَيِّدِي يَا يَهُوذَا أَعْيَادَكِ. أَوْفِي نُذُورَكِ، فَإِنَّهُ لَا يَعُودُ يَعْبُرُ فِيكِ أَيْضًا ٱلْمُهْلِكُ. قَدِ ٱنْقَرَضَ كُلُّهُ.","hūadẖā ʿalay̱ ٱl̊jibāli qadamā mubasẖĩriⁿ munādiⁿ biٱlsãlāmi! ʿayĩdī yā yahūdẖā ạảʿ̊yādaki. ạảẘfī nudẖūraki, fāi̹nãhu lā yaʿūdu yaʿ̊buru fīki ạảẙḍaⁿạ ٱl̊muh̊liku. qadi ٱn̊qaraḍa kulũhu."],[2,1,"قَدِ ٱرْتَفَعَتِ ٱلْمِقْمَعَةُ عَلَى وَجْهِكِ. ٱحْرُسِ ٱلْحِصْنَ. رَاقِبِ ٱلطَّرِيقَ. شَدِّدِ ٱلْحَقْوَيْنِ. مَكِّنِ ٱلْقُوَّةَ جِدًّا.","qadi ٱr̊tafaʿati ٱl̊miq̊maʿaẗu ʿalay̱ waj̊hiki. ٱḥ̊rusi ٱl̊ḥiṣ̊na. rāqibi ٱlṭãrīqa. sẖadĩdi ٱl̊ḥaq̊waẙni. makĩni ٱl̊qūãẗa jidaⁿ̃ạ."],[2,2,"فَإِنَّ ٱلرَّبَّ يَرُدُّ عَظَمَةَ يَعْقُوبَ كَعَظَمَةِ إِسْرَائِيلَ، لِأَنَّ ٱلسَّالِبِينَ قَدْ سَلَبُوهُمْ وَأَتْلَفُوا قُضْبَانَ كُرُومِهِمْ.","fāi̹nã ٱlrãbã yarudũ ʿaẓamaẗa yaʿ̊qūba kaʿaẓamaẗi ại̹s̊rāyỉyla, liạảnã ٱlsãạlibīna qad̊ salabūhum̊ wāảt̊lafūạ quḍ̊bāna kurūmihim̊."],[2,3,"تُرْسُ أَبْطَالِهِ مُحَمَّرٌ. رِجَالُ ٱلْجَيْشِ قِرْمِزِيُّونَ. ٱلْمَرْكَبَاتُ بِنَارِ ٱلْفُولَاذِ فِي يَوْمِ إِعْدَادِهِ. وَٱلسَّرْوُ يَهْتَزُّ.","tur̊su ạảb̊ṭālihi muḥamãruⁿ. rijālu ٱl̊jaẙsẖi qir̊mizīũwna. ٱl̊mar̊kabātu bināri ٱl̊fūlādẖi fī yaẘmi ại̹ʿ̊dādihi. waٱlsãr̊wu yah̊tazũ."],[2,4,"تَهِيجُ ٱلْمَرْكَبَاتُ فِي ٱلْأَزِقَّةِ. تَتَرَاكَضُ فِي ٱلسَّاحَاتِ. مَنْظَرُهَا كَمَصَابِيحَ. تَجْرِي كَٱلْبُرُوقِ.","tahīju ٱl̊mar̊kabātu fī ٱl̊ạảziqãẗi. tatarākaḍu fī ٱlsãạḥāti. man̊ẓaruhā kamaṣābīḥa. taj̊rī kaٱl̊burūqi."],[2,5,"يَذْكُرُ عُظَمَاءَهُ. يَتَعَثَّرُونَ فِي مَشْيِهِمْ. يُسْرِعُونَ إِلَى سُورِهَا، وَقَدْ أُقِيمَتِ ٱلْمِتْرَسَةُ.","yadẖ̊kuru ʿuẓamāʾahu. yataʿatẖãrūna fī masẖ̊yihim̊. yus̊riʿūna ại̹lay̱ sūrihā, waqad̊ ạủqīmati ٱl̊mit̊rasaẗu."],[2,6,"أَبْوَابُ ٱلْأَنْهَارِ ٱنْفَتَحَتْ، وَٱلْقَصْرُ قَدْ ذَابَ.","ạảb̊wābu ٱl̊ạản̊hāri ٱn̊fataḥat̊, waٱl̊qaṣ̊ru qad̊ dẖāba."],[2,7,"وَهُصَّبُ قَدِ ٱنْكَشَفَتْ. أُطْلِعَتْ. وَجَوَارِيهَا تَئِنُّ كَصَوْتِ ٱلْحَمَامِ ضَارِبَاتٍ عَلَى صُدُورِهِنَّ.","wahuṣãbu qadi ٱn̊kasẖafat̊. ạủṭ̊liʿat̊. wajawārīhā tayỉnũ kaṣaẘti ٱl̊ḥamāmi ḍāribātiⁿ ʿalay̱ ṣudūrihinã."],[2,8,"وَنِينَوَى كَبِرْكَةِ مَاءٍ مُنْذُ كَانَتْ، وَلَكِنَّهُمُ ٱلْآنَ هَارِبُونَ. «قِفُوا، قِفُوا!» وَلَا مُلْتَفِتٌ.","wanīnaway̱ kabir̊kaẗi māʾiⁿ mun̊dẖu kānat̊, walakinãhumu ٱl̊ậna hāribūna. «qifūạ, qifūạ!» walā mul̊tafituⁿ."],[2,9,"اِنْهَبُوا فِضَّةً. اِنْهَبُوا ذَهَبًا، فَلَا نِهَايَةَ لِلتُّحَفِ لِلْكَثْرَةِ مِنْ كُلِّ مَتَاعٍ شَهِيٍّ.","ạin̊habūạ fiḍãẗaⁿ. ạin̊habūạ dẖahabaⁿạ, falā nihāyaẗa liltũḥafi lil̊katẖ̊raẗi min̊ kulĩ matāʿiⁿ sẖahīiⁿ̃."],[2,10,"فَرَاغٌ وَخَلَاءٌ وَخَرَابٌ، وَقَلْبٌ ذَائِبٌ وَٱرْتِخَاءُ رُكَبٍ وَوَجَعٌ فِي كُلِّ حَقْوٍ. وَأَوْجُهُ جَمِيعِهِمْ تَجْمَعُ حُمْرَةً.","farāgẖuⁿ wakẖalāʾuⁿ wakẖarābuⁿ, waqal̊buⁿ dẖāyỉbuⁿ waٱr̊tikẖāʾu rukabiⁿ wawajaʿuⁿ fī kulĩ ḥaq̊wiⁿ. wāảẘjuhu jamīʿihim̊ taj̊maʿu ḥum̊raẗaⁿ."],[2,11,"أَيْنَ مَأْوَى ٱلْأُسُودِ وَمَرْعَى أَشْبَالِ ٱلْأُسُودِ؟ حَيْثُ يَمْشِي ٱلْأَسَدُ وَٱللَّبُوَةُ وَشِبْلُ ٱلْأَسَدِ، وَلَيْسَ مَنْ يُخَوِّفُ.","ạảẙna mā̊̉way̱ ٱl̊ạủsūdi wamar̊ʿay̱ ạảsẖ̊bāli ٱl̊ạủsūdi? ḥaẙtẖu yam̊sẖī ٱl̊ạảsadu waٱllãbūaẗu wasẖib̊lu ٱl̊ạảsadi, walaẙsa man̊ yukẖawĩfu."],[2,12,"ٱلْأَسَدُ ٱلْمُفْتَرِسُ لِحَاجةِ جِرَائِهِ، وَٱلْخَانِقُ لِأَجْلِ لَبُوَاتِهِ حَتَّى مَلَأَ مَغَارَاتِهِ فَرَائِسَ وَمَآوِيَهُ مُفْتَرَسَاتٍ.","ٱl̊ạảsadu ٱl̊muf̊tarisu liḥājẗi jirāyỉhi, waٱl̊kẖāniqu liạảj̊li labūātihi ḥatãy̱ malāả magẖārātihi farāyỉsa wamā̂wīahu muf̊tarasātiⁿ."],[2,13,"«هَا أَنَا عَلَيْكِ، يَقُولُ رَبُّ ٱلْجُنُودِ. فَأُحْرِقُ مَرْكَبَاتِكِ دُخَانًا، وَأَشْبَالُكِ يَأْكُلُهَا ٱلسَّيْفُ، وَأَقْطَعُ مِنَ ٱلْأَرْضِ فَرَائِسَكِ، وَلَا يُسْمَعُ أَيْضًا صَوْتُ رُسُلُكِ».","«hā ạảnā ʿalaẙki, yaqūlu rabũ ٱl̊junūdi. fāủḥ̊riqu mar̊kabātiki dukẖānaⁿạ, wāảsẖ̊bāluki yā̊̉kuluhā ٱlsãẙfu, wāảq̊ṭaʿu mina ٱl̊ạảr̊ḍi farāyỉsaki, walā yus̊maʿu ạảẙḍaⁿạ ṣaẘtu rusuluki»."],[3,1,"وَيْلٌ لِمَدِينَةِ ٱلدِّمَاءِ. كُلُّهَا مَلْآنَةٌ كَذِبًا وَخَطْفًا. لَا يَزُولُ ٱلِٱفْتِرَاسُ.","waẙluⁿ limadīnaẗi ٱldĩmāʾi. kulũhā mal̊ậnaẗuⁿ kadẖibaⁿạ wakẖaṭ̊faⁿạ. lā yazūlu ٱliٱf̊tirāsu."],[3,2,"صَوْتُ ٱلسَّوطِ وَصَوْتُ رَعْشَةِ ٱلْبَكَرِ، وَخَيْلٌ تَخُبُّ وَمَرْكَبَاتٌ تَقْفِزُ،","ṣaẘtu ٱlsãwṭi waṣaẘtu raʿ̊sẖaẗi ٱl̊bakari, wakẖaẙluⁿ takẖubũ wamar̊kabātuⁿ taq̊fizu,"],[3,3,"وَفُرْسَانٌ تَنْهَضُ، وَلَهِيبُ ٱلسَّيْفِ وَبَرِيقُ ٱلرُّمْحِ، وَكَثْرَةُ جَرْحَى، وَوَفْرَةُ قَتْلَى، وَلَا نِهَايَةَ لِلْجُثَثِ. يَعْثُرُونَ بِجُثَثِهِمْ.","wafur̊sānuⁿ tan̊haḍu, walahību ٱlsãẙfi wabarīqu ٱlrũm̊ḥi, wakatẖ̊raẗu jar̊ḥay̱, wawaf̊raẗu qat̊lay̱, walā nihāyaẗa lil̊jutẖatẖi. yaʿ̊tẖurūna bijutẖatẖihim̊."],[3,4,"مِنْ أَجْلِ زِنَى ٱلزَّانِيَةِ ٱلْحَسَنَةِ ٱلْجَمَالِ صَاحِبَةِ ٱلسِّحْرِ ٱلْبَائِعَةِ أُمَمًا بِزِنَاهَا، وَقَبَائِلَ بِسِحْرِهَا.","min̊ ạảj̊li zinay̱ ٱlzãạnīaẗi ٱl̊ḥasanaẗi ٱl̊jamāli ṣāḥibaẗi ٱlsĩḥ̊ri ٱl̊bāyỉʿaẗi ạủmamaⁿạ bizināhā, waqabāyỉla bisiḥ̊rihā."],[3,5,"«هَأَنَذَا عَلَيْكِ، يَقُولُ رَبُّ ٱلْجُنُودِ، فَأَكْشِفُ أَذْيَالَكِ إِلَى فَوْقِ وَجْهِكِ، وَأُرِي ٱلْأُمَمَ عَوْرَتَكِ وَٱلْمَمَالِكَ خِزْيَكِ.","«hāảnadẖā ʿalaẙki, yaqūlu rabũ ٱl̊junūdi, fāảk̊sẖifu ạảdẖ̊yālaki ại̹lay̱ faẘqi waj̊hiki, wāủrī ٱl̊ạủmama ʿaẘrataki waٱl̊mamālika kẖiz̊yaki."],[3,6,"وَأَطْرَحُ عَلَيْكِ أَوْسَاخًا، وَأُهِينُكِ وَأَجْعَلُكِ عِبْرَةً.","wāảṭ̊raḥu ʿalaẙki ạảẘsākẖaⁿạ, wāủhīnuki wāảj̊ʿaluki ʿib̊raẗaⁿ."],[3,7,"وَيَكُونُ كُلُّ مَنْ يَرَاكِ يَهْرُبُ مِنْكِ وَيَقُولُ: خَرِبَتْ نِينَوَى، مَنْ يَرْثِي لَهَا؟ مِنْ أَيْنَ أَطْلُبُ لَكِ مُعَزِّينَ؟».","wayakūnu kulũ man̊ yarāki yah̊rubu min̊ki wayaqūlu: kẖaribat̊ nīnaway̱, man̊ yar̊tẖī lahā? min̊ ạảẙna ạảṭ̊lubu laki muʿazĩyna?»."],[3,8,"هَلْ أَنْتِ أَفْضَلُ مِنْ نُوَ أَمُونَ ٱلْجَالِسَةِ بَيْنَ ٱلْأَنْهَارِ، حَوْلَهَا ٱلْمِيَاهُ ٱلَّتِي هِيَ حِصْنُ ٱلْبَحْرِ، وَمِنَ ٱلْبَحْرِ سُورُهَا؟","hal̊ ạản̊ti ạảf̊ḍalu min̊ nūa ạảmūna ٱl̊jālisaẗi baẙna ٱl̊ạản̊hāri, ḥaẘlahā ٱl̊mīāhu ٱlãtī hīa ḥiṣ̊nu ٱl̊baḥ̊ri, wamina ٱl̊baḥ̊ri sūruhā?"],[3,9,"كُوشٌ قُوَّتُهَا مَعَ مِصْرَ وَلَيْسَتْ نِهَايَةٌ. فُوطٌ وَلُوبِيمُ كَانُوا مَعُونَتَكِ.","kūsẖuⁿ qūãtuhā maʿa miṣ̊ra walaẙsat̊ nihāyaẗuⁿ. fūṭuⁿ walūbīmu kānūạ maʿūnataki."],[3,10,"هِيَ أَيْضًا قَدْ مَضَتْ إِلَى ٱلْمَنْفَى بِٱلسَّبْيِ، وَأَطْفَالُهَا حُطِّمَتْ فِي رَأْسِ جَمِيعِ ٱلْأَزِقَّةِ، وَعَلَى أَشْرَافِهَا أَلْقَوْا قُرْعَةً، وَجَمِيعُ عُظَمَائِهَا تَقَيَّدُوا بِٱلْقُيُودِ.","hīa ạảẙḍaⁿạ qad̊ maḍat̊ ại̹lay̱ ٱl̊man̊fay̱ biٱlsãb̊yi, wāảṭ̊fāluhā ḥuṭĩmat̊ fī rā̊̉si jamīʿi ٱl̊ạảziqãẗi, waʿalay̱ ạảsẖ̊rāfihā ạảl̊qaẘạ qur̊ʿaẗaⁿ, wajamīʿu ʿuẓamāyỉhā taqayãdūạ biٱl̊quyūdi."],[3,11,"أَنْتِ أَيْضًا تَسْكَرِينَ. تَكُونِينَ خَافِيَةً. أَنْتِ أَيْضًا تَطْلُبِينَ حِصْنًا بِسَبَبِ ٱلْعَدُوِّ.","ạản̊ti ạảẙḍaⁿạ tas̊karīna. takūnīna kẖāfīaẗaⁿ. ạản̊ti ạảẙḍaⁿạ taṭ̊lubīna ḥiṣ̊naⁿạ bisababi ٱl̊ʿadūĩ."],[3,12,"جَمِيعُ قِلَاعِكِ أَشْجَارُ تِينٍ بِٱلْبَوَاكِيرِ، إِذَا ٱنْهَزَّتْ تَسْقُطُ فِي فَمِ ٱلْآكِلِ.","jamīʿu qilāʿiki ạảsẖ̊jāru tīniⁿ biٱl̊bawākīri, ại̹dẖā ٱn̊hazãt̊ tas̊quṭu fī fami ٱl̊ậkili."],[3,13,"هُوَذَا شَعْبُكِ نِسَاءٌ فِي وَسَطِكِ! تَنْفَتِحُ لِأَعْدَائِكِ أَبْوَابُ أَرْضِكِ. تَأْكُلُ ٱلنَّارُ مَغَالِيقَكِ.","hūadẖā sẖaʿ̊buki nisāʾuⁿ fī wasaṭiki! tan̊fatiḥu liạảʿ̊dāyỉki ạảb̊wābu ạảr̊ḍiki. tā̊̉kulu ٱlnãạru magẖālīqaki."],[3,14,"اِسْتَقِي لِنَفْسِكِ مَاءً لِلْحِصَارِ. أَصْلِحِي قِلَاعَكِ. ٱدْخُلِي فِي ٱلطِّينِ وَدُوسِي فِي ٱلْمِلَاطِ. أَصْلِحِي ٱلْمِلْبَنَ.","ạis̊taqī linaf̊siki māʾaⁿ lil̊ḥiṣāri. ạảṣ̊liḥī qilāʿaki. ٱd̊kẖulī fī ٱlṭĩyni wadūsī fī ٱl̊milāṭi. ạảṣ̊liḥī ٱl̊mil̊bana."],[3,15,"هُنَاكَ تَأْكُلُكِ نَارٌ، يَقْطَعُكِ سَيْفٌ، يَأْكُلُكِ كَٱلْغَوْغَاءِ، تَكَاثَرِي كَٱلْغَوْغَاءِ. تَعَاظَمِي كَٱلْجَرَادِ!","hunāka tā̊̉kuluki nāruⁿ, yaq̊ṭaʿuki saẙfuⁿ, yā̊̉kuluki kaٱl̊gẖaẘgẖāʾi, takātẖarī kaٱl̊gẖaẘgẖāʾi. taʿāẓamī kaٱl̊jarādi!"],[3,16,"أَكْثَرْتِ تُجَّارَكِ أَكْثَرَ مِنْ نُجُومِ ٱلسَّمَاءِ. ٱلْغَوْغَاءُ جَنَّحَتْ وَطَارَتْ.","ạảk̊tẖar̊ti tujãạraki ạảk̊tẖara min̊ nujūmi ٱlsãmāʾi. ٱl̊gẖaẘgẖāʾu janãḥat̊ waṭārat̊."],[3,17,"رُؤَسَاؤُكِ كَٱلْجَرَادِ، وَوُلَاتُكِ كَحَرْجَلَةِ ٱلْجَرَادِ ٱلْحَالَّةِ عَلَى ٱلْجُدْرَانِ فِي يَوْمِ ٱلْبَرْدِ. تُشْرِقُ ٱلشَّمْسُ فَتَطِيرُ وَلَا يُعْرَفُ مَكَانُهَا أَيْنَ هُوَ.","rūảsāwủki kaٱl̊jarādi, wawulātuki kaḥar̊jalaẗi ٱl̊jarādi ٱl̊ḥālãẗi ʿalay̱ ٱl̊jud̊rāni fī yaẘmi ٱl̊bar̊di. tusẖ̊riqu ٱlsẖãm̊su fataṭīru walā yuʿ̊rafu makānuhā ạảẙna hūa."],[3,18,"نَعِسَتْ رُعَاتُكَ يَا مَلِكَ أَشُّورَ. ٱضْطَجَعَتْ عُظَمَاؤُكَ. تَشَتَّتَ شَعْبُكَ عَلَى ٱلْجِبَالِ وَلَا مَنْ يَجْمَعُ.","naʿisat̊ ruʿātuka yā malika ạảsẖũwra. ٱḍ̊ṭajaʿat̊ ʿuẓamāwủka. tasẖatãta sẖaʿ̊buka ʿalay̱ ٱl̊jibāli walā man̊ yaj̊maʿu."],[3,19,"لَيْسَ جَبْرٌ لِٱنْكِسَارِكَ. جُرْحُكَ عَدِيمُ ٱلشِّفَاءِ. كُلُّ ٱلَّذِينَ يَسْمَعُونَ خَبَرَكَ يُصَفِّقُونَ بِأَيْدِيهِمْ عَلَيْكَ، لِأَنَّهُ عَلَى مَنْ لَمْ يَمُرَّ شَرُّكَ عَلَى ٱلدَّوَامِ؟","laẙsa jab̊ruⁿ liٱn̊kisārika. jur̊ḥuka ʿadīmu ٱlsẖĩfāʾi. kulũ ٱlãdẖīna yas̊maʿūna kẖabaraka yuṣafĩqūna biạảẙdīhim̊ ʿalaẙka, liạảnãhu ʿalay̱ man̊ lam̊ yamurã sẖarũka ʿalay̱ ٱldãwāmi?"]],"bis-obbr":[[1,1,"Ol tok we i stap long buk ya, Hae God i soemaot long Profet Neham long wan vison*, blong tokbaot bigfala taon ya Nineve. Profet ya, hem i wan man Elkos.","Ol tok we i stap long buk ya, Hae God i soemaot long Profet Neham long wan vison*, blong tokbaot bigfala taon ya Nineve. Profet ya, hem i wan man Elkos."],[1,2,"Nao Profet Neham i talem se, “Hae God i no wantem nating blong man i biaen long hem, mo i biaen long narafala god long semtaem. Hem i kros we i kros, mo bambae i givim panis long olgeta we oli stap agens long hem.","Nao Profet Neham i talem se, “Hae God i no wantem nating blong man i biaen long hem, mo i biaen long narafala god long semtaem. Hem i kros we i kros, mo bambae i givim panis long olgeta we oli stap agens long hem."],[1,3,"Hem i no save kros kwik, be hem i gat paoa. Mo hem i no save letem olgeta we oli mekem nogud oli stap nomo olsem, hem i mas givim panis long olgeta. “Oltaem, long evri ples we hem i stap pas long hem, i gat waelwin mo hariken i go wetem hem. Taem hem i purumbut long graon, smok blong graon i kavremap olgeta ples olsem bigfala klaod.","Hem i no save kros kwik, be hem i gat paoa. Mo hem i no save letem olgeta we oli mekem nogud oli stap nomo olsem, hem i mas givim panis long olgeta. “Oltaem, long evri ples we hem i stap pas long hem, i gat waelwin mo hariken i go wetem hem. Taem hem i purumbut long graon, smok blong graon i kavremap olgeta ples olsem bigfala klaod."],[1,4,"Taem hem i tok long solwota, solwota ya i drae wantaem nomo. Hem i blokem ol bigfala reva, nao oli no moa ron. Hem i mekem ol gudfala ples long Basan oli drae, mo hem i mekem ol tri long bigfala hil ya Kamel oli drae. Ol gudgudfala flaoa long Lebanon, hem i mekem olgeta oli drae evriwan.","Taem hem i tok long solwota, solwota ya i drae wantaem nomo. Hem i blokem ol bigfala reva, nao oli no moa ron. Hem i mekem ol gudfala ples long Basan oli drae, mo hem i mekem ol tri long bigfala hil ya Kamel oli drae. Ol gudgudfala flaoa long Lebanon, hem i mekem olgeta oli drae evriwan."],[1,5,"Taem we hem i kamtru, ol bigbigfala hil oli seksek long fes blong hem, mo ol smosmol hil oli kam sofsof oli stap ronaot. Graon i seksek bigwan, mo wol ya wetem ol man we oli stap long hem, olgeta evriwan oli fraet, oli seksek.","Taem we hem i kamtru, ol bigbigfala hil oli seksek long fes blong hem, mo ol smosmol hil oli kam sofsof oli stap ronaot. Graon i seksek bigwan, mo wol ya wetem ol man we oli stap long hem, olgeta evriwan oli fraet, oli seksek."],[1,6,"?Sipos Hae God i kros tumas, hu i naf long hem? ?Sipos hem i kros we i kros olsem, hu bambae i save stap laef? Taem hem i kros, kros blong hem i kamaot olsem faea we i laet. Ol bigbigfala ston oli brobrok, oli kam olsem asis nomo long fes blong hem.","?Sipos Hae God i kros tumas, hu i naf long hem? ?Sipos hem i kros we i kros olsem, hu bambae i save stap laef? Taem hem i kros, kros blong hem i kamaot olsem faea we i laet. Ol bigbigfala ston oli brobrok, oli kam olsem asis nomo long fes blong hem."],[1,7,"“Hae God i gud tumas. Taem ol man blong hem oli stap long trabol, hem i save lukaot gud long olgeta. Hem i sefples blong olgeta we oli putum tingting blong olgeta i stap strong long hem.","“Hae God i gud tumas. Taem ol man blong hem oli stap long trabol, hem i save lukaot gud long olgeta. Hem i sefples blong olgeta we oli putum tingting blong olgeta i stap strong long hem."],[1,8,"Be ol enemi blong hem, hem bambae i spolemgud olgeta long reva we i ron bigwan, i kavremap evri ples. Mo olgeta we oli stap agens long hem, hem bambae i kilim olgeta evriwan i ded.","Be ol enemi blong hem, hem bambae i spolemgud olgeta long reva we i ron bigwan, i kavremap evri ples. Mo olgeta we oli stap agens long hem, hem bambae i kilim olgeta evriwan i ded."],[1,9,"“Ol man Nineve. ?Wanem plan ya we yufala i stap mekem agens long Hae God? Hem bambae i spolemgud yufala. I no gat man we i save agensem Hae God tu taem.","“Ol man Nineve. ?Wanem plan ya we yufala i stap mekem agens long Hae God? Hem bambae i spolemgud yufala. I no gat man we i save agensem Hae God tu taem."],[1,10,"!Yufala i man blong drong! Hem bambae i bonem yufala evriwan, nao yufala i lus olgeta, olsem grasnil mo drae gras we faea i kakae.","!Yufala i man blong drong! Hem bambae i bonem yufala evriwan, nao yufala i lus olgeta, olsem grasnil mo drae gras we faea i kakae."],[1,11,"I gat wan man i kamaot long yufala wetem ol rabis plan blong hem, mo hem i stap mekem plan agens long Hae God.”","I gat wan man i kamaot long yufala wetem ol rabis plan blong hem, mo hem i stap mekem plan agens long Hae God.”"],[1,12,"Nao profet i talem long ol laen* blong Isrel* se, “Olgeta. Yumi man blong Hae God, mo hem i toktok long yumi i talem se, ‘Ol man blong mi. I nating we ol man Asiria ya oli plante tumas, mo oli strong moa winim yufala, be mi bambae mi spolemgud olgeta, we bambae i no gat wan i stap. Fastaem mi mi bin mekem yufala i harem nogud, be naoia, bambae mi no moa save mekem olsem bakegen.","Nao profet i talem long ol laen* blong Isrel* se, “Olgeta. Yumi man blong Hae God, mo hem i toktok long yumi i talem se, ‘Ol man blong mi. I nating we ol man Asiria ya oli plante tumas, mo oli strong moa winim yufala, be mi bambae mi spolemgud olgeta, we bambae i no gat wan i stap. Fastaem mi mi bin mekem yufala i harem nogud, be naoia, bambae mi no moa save mekem olsem bakegen."],[1,13,"Paoa blong ol man Asiria ya we i stap holemtaet yufala, mi bambae mi spolem, mo ol jen ya we oli fasemtaet yufala long hem, mi bambae mi brebrekem, mi mekem yufala i gofri.’ ”","Paoa blong ol man Asiria ya we i stap holemtaet yufala, mi bambae mi spolem, mo ol jen ya we oli fasemtaet yufala long hem, mi bambae mi brebrekem, mi mekem yufala i gofri.’ ”"],[1,14,"Nao profet ya i talemaot we Hae God i tok agens long ol man Asiria, i talem se, “Ol man Asiria. Bambae yufala i no gat ol pikinini blong yufala blong holem nem blong yufala. Ol aedol ya we oli stap long ol haos blong ol god blong yufala, mi bambae mi spolem olgeta evriwan. Mi mi digimrere ol hol blong yufala finis, blong berem yufala long hem. I no stret nating blong yufala i stap laef.”","Nao profet ya i talemaot we Hae God i tok agens long ol man Asiria, i talem se, “Ol man Asiria. Bambae yufala i no gat ol pikinini blong yufala blong holem nem blong yufala. Ol aedol ya we oli stap long ol haos blong ol god blong yufala, mi bambae mi spolem olgeta evriwan. Mi mi digimrere ol hol blong yufala finis, blong berem yufala long hem. I no stret nating blong yufala i stap laef.”"],[1,15,"Nao profet i gohed i talem se, “Ol man Juda*. !Yufala i luk! I gat wan man blong karem tok, hem i aot long ol hil i stap kam. !Hem i stap kam wetem gudfala nius! Hem i stap kam blong talemaot we God i winim ol enemi blong yumi finis, mo yumi gat pis. I gud yumi gohed, yumi mekem ol lafet blong yumi, mo yumi givim ol presen ya we yumi bin promes* long God blong givim long hem. Neva bambae ol man nogud oli save kam insaed long graon blong yumi bakegen, blong spolem yumi. Hem i spolem olgeta evriwan finis we i no moa gat wan i stap.”","Nao profet i gohed i talem se, “Ol man Juda*. !Yufala i luk! I gat wan man blong karem tok, hem i aot long ol hil i stap kam. !Hem i stap kam wetem gudfala nius! Hem i stap kam blong talemaot we God i winim ol enemi blong yumi finis, mo yumi gat pis. I gud yumi gohed, yumi mekem ol lafet blong yumi, mo yumi givim ol presen ya we yumi bin promes* long God blong givim long hem. Neva bambae ol man nogud oli save kam insaed long graon blong yumi bakegen, blong spolem yumi. Hem i spolem olgeta evriwan finis we i no moa gat wan i stap.”"],[2,1,"Nao long vison* ya, Profet Neham i gohed, i talem se, “Ol man Nineve. Ol enemi oli kam finis blong faet agens long yufala. Olgeta ya oli strong tumas, oli gat paoa, mo bambae oli spolemgud yufala. Yufala i mas stanap rere blong blokem olgeta. Yufala i mas gad long ol rod, yufala i mas mekemrere blong faet.","Nao long vison* ya, Profet Neham i gohed, i talem se, “Ol man Nineve. Ol enemi oli kam finis blong faet agens long yufala. Olgeta ya oli strong tumas, oli gat paoa, mo bambae oli spolemgud yufala. Yufala i mas stanap rere blong blokem olgeta. Yufala i mas gad long ol rod, yufala i mas mekemrere blong faet."],[2,2,"(“Bambae Hae God i leftemap ol laen* blong Isrel* i givim hae nem mo paoa long olgeta bakegen. Bambae olgeta oli stap gud olsem fastaem, taem ol enemi oli no spolem olgeta yet.)","(“Bambae Hae God i leftemap ol laen* blong Isrel* i givim hae nem mo paoa long olgeta bakegen. Bambae olgeta oli stap gud olsem fastaem, taem ol enemi oli no spolem olgeta yet.)"],[2,3,"“Ol man Nineve. Ol soldia blong ol enemi ya blong yufala, olgeta evriwan oli putum yunifom we i red, mo oli karem ol sil we i red. Olgeta oli rere finis blong kam kilim yufala. Ol kat blong faet blong olgeta, oli saen we i saen. Ol hos blong faet blong olgeta oli stap jamjam, oli glad from we oli wantem go long faet.","“Ol man Nineve. Ol soldia blong ol enemi ya blong yufala, olgeta evriwan oli putum yunifom we i red, mo oli karem ol sil we i red. Olgeta oli rere finis blong kam kilim yufala. Ol kat blong faet blong olgeta, oli saen we i saen. Ol hos blong faet blong olgeta oli stap jamjam, oli glad from we oli wantem go long faet."],[2,4,"“Olbaot long ol rod blong taon, mo long ol bigfala open ples insaed long taon ya, ol kat blong faet blong yufala oli stap resis krangke olbaot i go i kam, we oli spid olsem laetning, mo oli stap saen olsem toslaet.","“Olbaot long ol rod blong taon, mo long ol bigfala open ples insaed long taon ya, ol kat blong faet blong yufala oli stap resis krangke olbaot i go i kam, we oli spid olsem laetning, mo oli stap saen olsem toslaet."],[2,5,"Ol komanda blong yufala oli singaot ol kapten blong olgeta blong oli kam faet, mo taem oli kam, oli hareap we oli stap stambol from. “Nao ol enemi oli resis i go long bigfala stonwol blong taon ya, oli stanemap bigfala sil blong blokemgud ol man ya blong olgeta we oli stap pusum bigfala wud ya blong brekemdaon stonwol ya, blong ol ara blong yufala i no save kasem olgeta.","Ol komanda blong yufala oli singaot ol kapten blong olgeta blong oli kam faet, mo taem oli kam, oli hareap we oli stap stambol from. “Nao ol enemi oli resis i go long bigfala stonwol blong taon ya, oli stanemap bigfala sil blong blokemgud ol man ya blong olgeta we oli stap pusum bigfala wud ya blong brekemdaon stonwol ya, blong ol ara blong yufala i no save kasem olgeta."],[2,6,"Oli openem ol doa blong reva, nao wota i go flatem haos blong woman god blong yufala.","Oli openem ol doa blong reva, nao wota i go flatem haos blong woman god blong yufala."],[2,7,"Oli tektekemaot ol gudgudfala samting blong woman god ya, nao oli karemaot hem, oli tekem i go, mo ol woman blong wok blong hem oli harem nogud, oli krae we oli krae, olsem sotleg*. Oli stap kilkilim jes blong olgeta, from we oli harem nogud tumas.","Oli tektekemaot ol gudgudfala samting blong woman god ya, nao oli karemaot hem, oli tekem i go, mo ol woman blong wok blong hem oli harem nogud, oli krae we oli krae, olsem sotleg*. Oli stap kilkilim jes blong olgeta, from we oli harem nogud tumas."],[2,8,"Taon ya Nineve i olsem wan raonwota, we ol wota blong hem i stap ronaot. Ol man blong hem oli stap ronronwe. Taem ol haeman blong olgeta oli singaot blong blokem olgeta, oli no harem tok blong olgeta nating.","Taon ya Nineve i olsem wan raonwota, we ol wota blong hem i stap ronaot. Ol man blong hem oli stap ronronwe. Taem ol haeman blong olgeta oli singaot blong blokem olgeta, oli no harem tok blong olgeta nating."],[2,9,"“Nao ol enemi oli stap singsingaot se, ‘Olgeta. !Bigfala taon ya Nineve i fulap long ol gudgudfala samting! !Yumi go tekemaot ol silva, mo ol gol blong olgeta!","“Nao ol enemi oli stap singsingaot se, ‘Olgeta. !Bigfala taon ya Nineve i fulap long ol gudgudfala samting! !Yumi go tekemaot ol silva, mo ol gol blong olgeta!"],[2,10,"Taon ya i kam nogud olgeta. I no moa gat wan samting i stap long hem. Ol man blong hem oli fraet tumas, we leg blong olgeta i seksek from. Paoa blong olgeta i lus, we fes blong olgeta i kam nogud olgeta.","Taon ya i kam nogud olgeta. I no moa gat wan samting i stap long hem. Ol man blong hem oli fraet tumas, we leg blong olgeta i seksek from. Paoa blong olgeta i lus, we fes blong olgeta i kam nogud olgeta."],[2,11,"Bifo, bigfala taon ya i gat olgeta paoa. Hem i olsem wan hol blong laeon, we laeon i stap fidim ol pikinini blong hem long hem, mo man laeon wetem woman laeon, tufala i stap haed long hem wetem ol pikinini blong tufala. Ol man blong taon ya oli olsem laeon we i stap go kilim ol anamol, nao i karem i kam long hol blong hem, mo i terem long ol smosmol pis blong woman blong hem wetem ol pikinini blong hem oli kakae, nao hol ya i fulap gud long ol mit blong ol anamol. ?Be naoia olsem wanem long bigfala taon ya?’","Bifo, bigfala taon ya i gat olgeta paoa. Hem i olsem wan hol blong laeon, we laeon i stap fidim ol pikinini blong hem long hem, mo man laeon wetem woman laeon, tufala i stap haed long hem wetem ol pikinini blong tufala. Ol man blong taon ya oli olsem laeon we i stap go kilim ol anamol, nao i karem i kam long hol blong hem, mo i terem long ol smosmol pis blong woman blong hem wetem ol pikinini blong hem oli kakae, nao hol ya i fulap gud long ol mit blong ol anamol. ?Be naoia olsem wanem long bigfala taon ya?’",12],[2,13,"Nao long vison ya, profet i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man Nineve. Mi mi enemi blong yufala. Mi bambae mi bonem ol kat blong faet blong yufala. Ol soldia blong yufala, bambae olgeta evriwan oli ded long taem blong faet. Mo olgeta samting we yufala i tekemaot long ol enemi blong yufala, mi bambae mi tekemaot olgeta evriwan. Bambae i no moa gat man blong karem tok blong yufala, blong ol man oli harem tok blong yufala bakegen.’ ”","Nao long vison ya, profet i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man Nineve. Mi mi enemi blong yufala. Mi bambae mi bonem ol kat blong faet blong yufala. Ol soldia blong yufala, bambae olgeta evriwan oli ded long taem blong faet. Mo olgeta samting we yufala i tekemaot long ol enemi blong yufala, mi bambae mi tekemaot olgeta evriwan. Bambae i no moa gat man blong karem tok blong yufala, blong ol man oli harem tok blong yufala bakegen.’ ”"],[3,1,"Nao long vison* ya Profet Neham i gohed i talem se, “Ol man Nineve. !Sore tumas long yufala! Yufala i man blong giaman, mo oltaem, yufala i man blong kilim man i ded. Ples blong yufala i fulap long ol gudgudfala samting we yufala i tekemaot long ol narafala man long taem blong faet. Naoia ol enemi blong yufala oli kam finis blong tekemaot ol samting ya long yufala bakegen.","Nao long vison* ya Profet Neham i gohed i talem se, “Ol man Nineve. !Sore tumas long yufala! Yufala i man blong giaman, mo oltaem, yufala i man blong kilim man i ded. Ples blong yufala i fulap long ol gudgudfala samting we yufala i tekemaot long ol narafala man long taem blong faet. Naoia ol enemi blong yufala oli kam finis blong tekemaot ol samting ya long yufala bakegen."],[3,2,"!Yufala i lesin! Yufala i harem noes blong wip, mo noes blong kat blong faet, mo noes blong ol wil blong hem, mo noes blong ol hos we oli stap resis.","!Yufala i lesin! Yufala i harem noes blong wip, mo noes blong kat blong faet, mo noes blong ol wil blong hem, mo noes blong ol hos we oli stap resis."],[3,3,"Olgeta we oli stap resis long hos oli stap go fastaem. Naef blong faet blong olgeta i saen we i saen, mo ol spia blong olgeta i saen gud. Ol dedbodi oli hip i stap, oli plante tumas, man i no save kaontem. Oli stap olbaot, we ol man oli stap stambol long olgeta.","Olgeta we oli stap resis long hos oli stap go fastaem. Naef blong faet blong olgeta i saen we i saen, mo ol spia blong olgeta i saen gud. Ol dedbodi oli hip i stap, oli plante tumas, man i no save kaontem. Oli stap olbaot, we ol man oli stap stambol long olgeta."],[3,4,"“Nineve. Yu yu olsem woman blong rod stret, we i naes we i naes. Hem i fulap long ol fasin blong pulum ae blong man, be i blong kilim man i ded nomo. Yu yu stap pulum ol man blong ol narafala kantri long ol rabis fasin blong yu, mo yu stap holem olgeta oli kam slef* blong yu, nao Hae God i stap panisim yu from.","“Nineve. Yu yu olsem woman blong rod stret, we i naes we i naes. Hem i fulap long ol fasin blong pulum ae blong man, be i blong kilim man i ded nomo. Yu yu stap pulum ol man blong ol narafala kantri long ol rabis fasin blong yu, mo yu stap holem olgeta oli kam slef* blong yu, nao Hae God i stap panisim yu from."],[3,5,"“Hae God i gat olgeta paoa, mo hem i talem se, ‘Nineve. Mi bambae mi panisim yu, mi tekemaot olgeta samting we yu yu gat. Nao bambae mi letem olgeta ples long wol oli luk yu, mo bambae oli luk we yu yu sem tumas.","“Hae God i gat olgeta paoa, mo hem i talem se, ‘Nineve. Mi bambae mi panisim yu, mi tekemaot olgeta samting we yu yu gat. Nao bambae mi letem olgeta ples long wol oli luk yu, mo bambae oli luk we yu yu sem tumas."],[3,6,"Mi bambae mi mekem yu yu sem, blong soemaot we mi no tinghevi long yu nating, mo bambae mi kavremap yu long ol doti. Mo taem ol man oli stap lukluk yu, bambae oli fraet tumas.","Mi bambae mi mekem yu yu sem, blong soemaot we mi no tinghevi long yu nating, mo bambae mi kavremap yu long ol doti. Mo taem ol man oli stap lukluk yu, bambae oli fraet tumas."],[3,7,"Olgeta man we oli luk yu, bambae oli sek, oli tanemraon oli gobak. Bambae oli stap taltalem se, “Naoia, Nineve i kam nogud finis. ?Hu bambae i save go krae long hem?” Mi mi no save faenem wan man nating blong mekem yu yu harem gud bakegen.’ ”","Olgeta man we oli luk yu, bambae oli sek, oli tanemraon oli gobak. Bambae oli stap taltalem se, “Naoia, Nineve i kam nogud finis. ?Hu bambae i save go krae long hem?” Mi mi no save faenem wan man nating blong mekem yu yu harem gud bakegen.’ ”"],[3,8,"Nao profet i talem se, “Nineve. ?Yu yu ting se paoa blong yu i strong moa winim taon ya Tebes, we i kaptel blong Ijip? Bigfala taon ya, Nael Reva i goraon long hem, olsem bigfala stonwol blong hem, mo i blokem hem blong ol enemi oli no spolem hem.","Nao profet i talem se, “Nineve. ?Yu yu ting se paoa blong yu i strong moa winim taon ya Tebes, we i kaptel blong Ijip? Bigfala taon ya, Nael Reva i goraon long hem, olsem bigfala stonwol blong hem, mo i blokem hem blong ol enemi oli no spolem hem."],[3,9,"Taon ya i rulum Itiopia mo Ijip, mo paoa blong hem i strong tumas, we i no gat en blong hem. Mo tufala kantri ya Put mo Libia, tufala tu i fren blong hem.","Taon ya i rulum Itiopia mo Ijip, mo paoa blong hem i strong tumas, we i no gat en blong hem. Mo tufala kantri ya Put mo Libia, tufala tu i fren blong hem."],[3,10,"Nating we hem i gat paoa olsem, be ol enemi blong hem oli kam tekemaot olgeta man blong hem oli go stap wok slef long narafala kantri. Mo oli kilim ol pikinini blong olgeta, gogo oli ded we oli stap olbaot nomo long ol kona blong ol rod. Mo oli holem ol haeman blong olgeta, oli fasem olgeta long ol jen, oli tekem olgeta i go, nao oli seraot ol man ya blong oli slef blong olgeta.","Nating we hem i gat paoa olsem, be ol enemi blong hem oli kam tekemaot olgeta man blong hem oli go stap wok slef long narafala kantri. Mo oli kilim ol pikinini blong olgeta, gogo oli ded we oli stap olbaot nomo long ol kona blong ol rod. Mo oli holem ol haeman blong olgeta, oli fasem olgeta long ol jen, oli tekem olgeta i go, nao oli seraot ol man ya blong oli slef blong olgeta."],[3,11,"“Nineve. Bambae ol enemi blong yu oli mekem sem fasin long yu. Yu tu, bambae yu stap wokbaot olbaot, olsem wan man we i drong, mo bambae yu traem blong ronwe long olgeta.","“Nineve. Bambae ol enemi blong yu oli mekem sem fasin long yu. Yu tu, bambae yu stap wokbaot olbaot, olsem wan man we i drong, mo bambae yu traem blong ronwe long olgeta."],[3,12,"Ol strong ples blong haed blong yu we yu trastem olgeta, be oli no strong nating, oli olsem tri we ol frut blong hem oli raep finis. Nao sipos man i seksekem, wantaem nomo bambae ol frut blong hem oli folfoldaon i go stret long maot blong hem.","Ol strong ples blong haed blong yu we yu trastem olgeta, be oli no strong nating, oli olsem tri we ol frut blong hem oli raep finis. Nao sipos man i seksekem, wantaem nomo bambae ol frut blong hem oli folfoldaon i go stret long maot blong hem."],[3,13,"Ol soldia blong yu oli olsem ol woman nomo, oli no strong nating. Long kantri blong yu, ol doa* blong ol stonwol blong ol taon blong hem oli open i stap, i no gat wan samting blong blokem ol enemi we oli stap kam blong faet long yu. Ol wud we i gokros long ol doa ya blong lokemgud, faea bambae i bonem olgeta evriwan.","Ol soldia blong yu oli olsem ol woman nomo, oli no strong nating. Long kantri blong yu, ol doa* blong ol stonwol blong ol taon blong hem oli open i stap, i no gat wan samting blong blokem ol enemi we oli stap kam blong faet long yu. Ol wud we i gokros long ol doa ya blong lokemgud, faea bambae i bonem olgeta evriwan."],[3,14,"Naoia, yufala i mas mekemrere ol samting, from we ol enemi blong yufala oli stap kam klosap blong raonem taon blong yufala blong faet agens long yufala. Yufala i go kasem ol wota blong dring blong yufala i stap rere, mo yufala i mekem ol strong ples blong haed blong yufala oli kam strong moa. Mo yufala i tekem red graon, yufala i purumpurumbut long hem blong i kam sofsof, blong wokem ol brikis i rere, mo yufala i mekemrere ol masin blong wokem ol brikis ya.","Naoia, yufala i mas mekemrere ol samting, from we ol enemi blong yufala oli stap kam klosap blong raonem taon blong yufala blong faet agens long yufala. Yufala i go kasem ol wota blong dring blong yufala i stap rere, mo yufala i mekem ol strong ples blong haed blong yufala oli kam strong moa. Mo yufala i tekem red graon, yufala i purumpurumbut long hem blong i kam sofsof, blong wokem ol brikis i rere, mo yufala i mekemrere ol masin blong wokem ol brikis ya."],[3,15,"Be nating we bambae yufala i mekem ol samting ya, no yufala i mekem sam samting moa blong blokem yufala, be ol enemi blong yufala bambae oli bonem sam long yufala i ded, mo bambae oli kilim ol narafala i ded long naef blong faet. Bambae oli kilim yufala evriwan i ded, olsem we ol lokis* oli flatemgud ol kakae long garen*. “Yufala i plante tumas olsem ol lokis.","Be nating we bambae yufala i mekem ol samting ya, no yufala i mekem sam samting moa blong blokem yufala, be ol enemi blong yufala bambae oli bonem sam long yufala i ded, mo bambae oli kilim ol narafala i ded long naef blong faet. Bambae oli kilim yufala evriwan i ded, olsem we ol lokis* oli flatemgud ol kakae long garen*. “Yufala i plante tumas olsem ol lokis."],[3,16,"Ol bisnesman long ples blong yufala oli plante we plante, oli winim ol sta long skae. Be naoia ol man ya oli lus finis. Olgeta evriwan oli flae i go olsem ol lokis.","Ol bisnesman long ples blong yufala oli plante we plante, oli winim ol sta long skae. Be naoia ol man ya oli lus finis. Olgeta evriwan oli flae i go olsem ol lokis."],[3,17,"Ol haeman blong yufala oli plante tumas oli hip olsem ol lokis we oli stap hivap wanples long stonwol long koltaem. Be taem san i stap kam antap, olgeta i flae i go, we i no gat man i save weples oli go long hem.","Ol haeman blong yufala oli plante tumas oli hip olsem ol lokis we oli stap hivap wanples long stonwol long koltaem. Be taem san i stap kam antap, olgeta i flae i go, we i no gat man i save weples oli go long hem."],[3,18,"“King blong Asiria. Ol distrikejen* blong yu, olgeta evriwan oli ded. Ol haeman blong yu oli slip we neva bambae oli girap bakegen. Ol man blong yu oli sut wanwan finis i go antap long hil, mo i no gat man blong tekem olgeta i kambak bakegen long ples blong olgeta.","“King blong Asiria. Ol distrikejen* blong yu, olgeta evriwan oli ded. Ol haeman blong yu oli slip we neva bambae oli girap bakegen. Ol man blong yu oli sut wanwan finis i go antap long hil, mo i no gat man blong tekem olgeta i kambak bakegen long ples blong olgeta."],[3,19,"Ol rabis fasin ya we yu yu stap mekem bifo kam kasem tede, i kasem olgeta man, mo oli stap harem nogud tumas from. Bambae soa blong yu i no save finis, mo i no gat wan samting blong mekem soa ya i kam gud bakegen. Olgeta man we oli harem nius blong ol samting ya, oli harem gud tumas, oli klapem han blong olgeta from.”","Ol rabis fasin ya we yu yu stap mekem bifo kam kasem tede, i kasem olgeta man, mo oli stap harem nogud tumas from. Bambae soa blong yu i no save finis, mo i no gat wan samting blong mekem soa ya i kam gud bakegen. Olgeta man we oli harem nius blong ol samting ya, oli harem gud tumas, oli klapem han blong olgeta from.”"]]}};